  // V34.4 SAVE FIX · mantiene exactamente el guardado histórico de PokéSenda
  const SAVE_KEY = window.PokeSendaActiveSaveKey || "pokesenda_beta1_save_v1";
  const LEGACY_SAVE_KEY = "pokesenda_beta1_legacy_disabled_v1";
