  const $ = id => document.getElementById(id);

  // V36.40.33 · Modal de confirmación propio. No usa diálogos nativos y por tanto no rompe fullscreen.
  let pkConfirmResolve=null,pkConfirmPausedRun=false;
  function ensurePkConfirmDialog(){
    let overlay=$("pkConfirmOverlay");if(overlay)return overlay;
    overlay=document.createElement("div");overlay.id="pkConfirmOverlay";overlay.className="pk-confirm-overlay hidden";overlay.setAttribute("role","dialog");overlay.setAttribute("aria-modal","true");overlay.setAttribute("aria-labelledby","pkConfirmTitle");
    overlay.innerHTML=`<div id="pkConfirmBox" class="pk-confirm-box" onclick="event.stopPropagation()">
      <div class="pk-confirm-head"><div id="pkConfirmSymbol" class="pk-confirm-symbol">?</div><div><div id="pkConfirmTitle" class="pk-confirm-title">Confirmar</div><div class="pk-confirm-kicker">PokéSenda</div></div></div>
      <div id="pkConfirmBody" class="pk-confirm-body"></div>
      <div class="pk-confirm-actions"><button id="pkConfirmCancel" class="btn pk-confirm-cancel" type="button">Cancelar</button><button id="pkConfirmOk" class="btn pk-confirm-ok" type="button">Confirmar</button></div>
    </div>`;
    document.body.appendChild(overlay);
    const finish=ok=>{
      if(overlay.classList.contains("hidden"))return;
      overlay.classList.add("hidden");
      const resolve=pkConfirmResolve;pkConfirmResolve=null;
      if(pkConfirmPausedRun&&typeof run!=="undefined"&&run&&run.paused&&!run.rewardPending&&!evolutionModalOpen){try{resumeRun(false);}catch(_){ }}
      pkConfirmPausedRun=false;
      if(resolve)resolve(!!ok);
    };
    $("pkConfirmCancel").addEventListener("click",()=>finish(false));
    $("pkConfirmOk").addEventListener("click",()=>finish(true));
    overlay.addEventListener("click",()=>finish(false));
    document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!overlay.classList.contains("hidden")){e.preventDefault();e.stopPropagation();finish(false);}},true);
    overlay._pkFinish=finish;
    return overlay;
  }
  function gameConfirm({title="Confirmar acción",message="",confirmText="Confirmar",cancelText="Cancelar",tone="primary",symbol="?",showCancel=true}={}){
    const overlay=ensurePkConfirmDialog();
    if(pkConfirmResolve&&overlay._pkFinish)overlay._pkFinish(false);
    const box=$("pkConfirmBox");box.className=`pk-confirm-box ${tone||"primary"}`;
    $("pkConfirmTitle").textContent=title;
    $("pkConfirmBody").textContent=message;
    $("pkConfirmOk").textContent=confirmText;
    $("pkConfirmCancel").textContent=cancelText;
    $("pkConfirmCancel").classList.toggle("hidden",showCancel===false);
    $("pkConfirmSymbol").textContent=symbol;
    // Un confirm nativo detenía el hilo. Para conservar ese comportamiento visual, pausamos una expedición activa mientras el modal está abierto.
    pkConfirmPausedRun=!!(typeof run!=="undefined"&&run&&!run.paused);
    if(pkConfirmPausedRun){try{pauseRun(false);}catch(_){pkConfirmPausedRun=false;}}
    overlay.classList.remove("hidden");
    setTimeout(()=>$("pkConfirmOk")?.focus(),0);
    return new Promise(resolve=>{pkConfirmResolve=resolve;});
  }
  window.PokeSendaGameConfirm=gameConfirm;
  window.PokeSendaGameAlert=function({title="PokéSenda",message="",confirmText="Cerrar",tone="primary",symbol="ℹ️"}={}){
    return gameConfirm({title,message,confirmText,cancelText:"",tone,symbol,showCancel:false});
  };
  const ROUTE101_MUSIC_SRC = $("bgMusic")?.getAttribute("src") || "";
  const MUSIC_TRACKS = {
    classic_menu:{name:"OP Red",sourceId:"menuMusic"},
    route101:{name:"Route 101",sourceId:null},
    bills_house:{name:"To Bill's House",sourceId:"musicBillsSource"},
    route1:{name:"Route 1",sourceId:"musicRoute1Source"},
    driftveil:{name:"Driftveil City",sourceId:"musicDriftveilSource"},
    littleroot:{name:"Littleroot Town",sourceId:"musicLittlerootSource"}
  };
  function musicTrackSource(key){
    if(key==="route101")return ROUTE101_MUSIC_SRC;
    const def=MUSIC_TRACKS[key];return def?.sourceId?($(def.sourceId)?.getAttribute("src")||""):"";
  }
  const REGION_DEX_MAX=window.PokeSendaRegionBoot?.isHoennClone?386:151;
  const spriteUrl = dex => `${SPRITE_BASE}${dex}.png`;
  const shinySpriteUrl = dex => `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/shiny/${dex}.png`;
  // V36.64.15 · Motor visual Pokémon global: el GIF nativo vive en el DOM y nunca depende de x1/x2/x4.
  const POKEMON_ANIM_BASE="https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-v/black-white/animated/";
  function pokemonAnimatedSpriteUrl(dex,back=false,shiny=false){
    dex=Math.max(1,Math.floor(Number(dex)||1));
    const animate=window.PokeSendaPokemonGifAllowed?.()??(!window.matchMedia('(max-width: 980px)').matches&&!document.documentElement.classList.contains("no-anim"));
    if(!animate)return `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${back?(shiny?"back/shiny/":"back/"):(shiny?"shiny/":"")}${dex}.png`;
    return POKEMON_ANIM_BASE+(back?(shiny?"back/shiny/":"back/"):(shiny?"shiny/":""))+dex+".gif";
  }
  function pokemonStaticSpriteUrl(dex,shiny=false){dex=Math.max(1,Math.floor(Number(dex)||1));return shiny?shinySpriteUrl(dex):spriteUrl(dex);}
  function ownedAnimatedSpriteUrl(id,back=false){const st=ownedStage(id),shiny=isOwnedShinyEquipped(id);return pokemonAnimatedSpriteUrl(st.dex,!!back,shiny);}
  function pkCaptureStablePokemonImgs(root){const m=new Map();root?.querySelectorAll?.("img[data-pk-sprite-key]").forEach(img=>{const k=img.dataset.pkSpriteKey;if(k&&!m.has(k))m.set(k,img);});return m;}
  function pkRestoreStablePokemonImgs(root,old){if(!root||!old?.size)return;root.querySelectorAll("img[data-pk-sprite-key]").forEach(img=>{const k=img.dataset.pkSpriteKey,prev=old.get(k);if(!prev||prev===img)return;const want=img.getAttribute("src")||"",had=prev.getAttribute("src")||"";if(want!==had)return;prev.className=img.className;prev.alt=img.alt;for(const a of [...img.attributes])if(a.name.startsWith("data-")&&a.name!=="data-pk-sprite-key")prev.setAttribute(a.name,a.value);img.replaceWith(prev);});}
  const SHINY_CAPTURE_DENOMINATOR=1536;
  function shinyTreeRelativeBonus(){
    const rank=id=>{try{return Math.max(0,Number(skillRank(id)||0));}catch(_){return 0;}};
    return .08*rank("f15")+.10*rank("f16")+(rank("f17")>=1?.14:0);
  }
  function shinyDexCompletionParts(){const region=window.PokeSendaRegionBoot?.isHoennClone?"hoenn":"kanto";return window.PokeSendaShinyDexBonus?.parts?.(region)||{regional:0,global:0,total:0};}
  function shinyCaptureChance(){const dexBonus=Number(shinyDexCompletionParts().total||0);return Math.min(.01,(1/SHINY_CAPTURE_DENOMINATOR)*(1+shinyTreeRelativeBonus()+dexBonus));}
  function shinyEffectiveDenominator(){return Math.max(1,Math.round(1/shinyCaptureChance()));}
  function shinyRateText(){const chance=shinyCaptureChance(),pct=(chance*100).toFixed(4).replace(".",","),tree=shinyTreeRelativeBonus(),dex=shinyDexCompletionParts(),den=shinyEffectiveDenominator(),tags=[];if(tree>0)tags.push(`+${Math.round(tree*100)}% Árbol`);if(dex.regional>0)tags.push(`+${Math.round(dex.regional*100)}% Pokédex`);if(dex.global>0)tags.push(`+${Math.round(dex.global*100)}% Global`);return `✨ Shiny ${pct}% (${tags.length?"≈":""}1/${den.toLocaleString("es-CL")}${tags.length?` · ${tags.join(" · ")}`:""})`;}
  function rollCaptureShiny(){return Math.random()<shinyCaptureChance();}
  function ensureShinyRoll(rolled){if(rolled&&typeof rolled.shiny!=="boolean")rolled.shiny=rollCaptureShiny();return rolled;}
  function shinyDexSet(){return new Set((state?.shinyDex||[]).map(Number));}
  function shinyDexCount(){return shinyDexSet().size;}
  function pokemonHasShinyStage(id,stageIndex=null){const p=state?.progress?.[id];if(!p)return false;const idx=stageIndex==null?Number(p.stageIndex||0):Number(stageIndex);return Array.isArray(p.shinyStages)&&p.shinyStages.includes(idx);}
  function isOwnedShinyEquipped(id){const p=state?.progress?.[id];return !!p?.shinyEquipped&&pokemonHasShinyStage(id,p.stageIndex);}
  function ownedVisualSpriteUrl(id){const st=ownedStage(id);return isOwnedShinyEquipped(id)?shinySpriteUrl(st.dex):spriteUrl(st.dex);}
  function registerShinyDex(dex){dex=Number(dex);if(!dex||dex<1||dex>REGION_DEX_MAX)return false;state.shinyDex=Array.isArray(state.shinyDex)?state.shinyDex:[];const fresh=!state.shinyDex.includes(dex);if(fresh)state.shinyDex.push(dex);return fresh;}
  function registerCapturedShiny(id,cap){if(!cap?.stage)return false;const dex=Number(cap.stage.dex),isNewVariant=registerShinyDex(dex);state.shinyCaptureCount=Math.max(0,Number(state.shinyCaptureCount||0))+1;const p=state.progress?.[id];if(p){p.shinyStages=Array.isArray(p.shinyStages)?p.shinyStages:[];const idx=Math.max(0,Number(cap.stageIndex||0));if(!p.shinyStages.includes(idx))p.shinyStages.push(idx);if(Number(p.stageIndex||0)===idx)p.shinyEquipped=true;}markDexUnread(dex);return isNewVariant;}
  function setPokemonShinyVariant(id,useShiny){const p=state.progress?.[id];if(!p)return;if(useShiny&&!pokemonHasShinyStage(id)){toast("Aún no has capturado la variante Shiny de esta forma");return;}p.shinyEquipped=!!useShiny;save();renderEverything();if(selectedPokemonId===id)renderCards();toast(`${ownedStage(id).name}: variante ${useShiny?"✨ Shiny":"normal"} equipada`);}
  function shinyVariantSelectorHTML(id){const p=state.progress?.[id],st=p?ownedStage(id):null;if(!p||!st||!pokemonHasShinyStage(id))return "";const shiny=!!p.shinyEquipped;return `<div class="shiny-variant-panel"><div class="shiny-variant-head"><b>✨ Variante visual desbloqueada</b><small>Solo cambia apariencia · no modifica estadísticas</small></div><div class="shiny-variant-options"><button class="shiny-variant-btn ${!shiny?"active":""}" data-shiny-use="normal" data-shiny-id="${id}"><img src="${spriteUrl(st.dex)}" alt="${st.name} normal"><span><b>Normal</b><small>${!shiny?"En uso":"Usar esta variante"}</small></span></button><button class="shiny-variant-btn shiny ${shiny?"active":""}" data-shiny-use="shiny" data-shiny-id="${id}"><img src="${shinySpriteUrl(st.dex)}" alt="${st.name} Shiny"><span><b>★ Shiny</b><small>${shiny?"En uso":"Usar esta variante"}</small></span></button></div></div>`;}
  // V36.64.10 · Vista Shiny seleccionable dentro de la Pokédex (independiente de la variante equipada).
  function dexShinyViewSet(){state.dexShinyView=Array.isArray(state.dexShinyView)?[...new Set(state.dexShinyView.map(Number).filter(d=>d>=1&&d<=REGION_DEX_MAX&&(state.shinyDex||[]).includes(d)))]:[];return new Set(state.dexShinyView);}
  function dexUsesShinyView(dex){dex=Number(dex);return (state.shinyDex||[]).includes(dex)&&dexShinyViewSet().has(dex);}
  function dexVisualSpriteUrl(dex){return dexUsesShinyView(dex)?shinySpriteUrl(Number(dex)):spriteUrl(Number(dex));}
  function setDexShinyView(dex,useShiny){dex=Number(dex);if(!dex||!(state.shinyDex||[]).includes(dex))return false;const set=dexShinyViewSet();if(useShiny)set.add(dex);else set.delete(dex);state.dexShinyView=[...set].sort((a,b)=>a-b);save();renderPokedex();return true;}

