  function stages(...items){ return items.map(x=>({name:x[0],dex:x[1],level:x[2],types:x[3],method:x[4]||"level",evoItem:x[5]||null})); }
  function family(name, attackType, profile, stats, stageData, move, enemyMode="ranged", evoNote=""){
    return {name,attackType,profile,baseHp:stats[0],hpGrowth:stats[1],baseAtk:stats[2],atkGrowth:stats[3],baseCd:stats[4],stages:stageData,move,enemyMode,evoNote};
  }

