  // V33.5 · Las tres evoluciones de Eevee pasan a ser Pokémon poseíbles independientes.
  // La familia original conserva las cuatro entradas solo como referencia de Pokédex/lore.
  const EEVEE_EVOLUTION_IDS=["vaporeon","jolteon","flareon"];
  const EEVEE_EVOLUTION_BY_STONE={water_stone:"vaporeon",thunder_stone:"jolteon",fire_stone:"flareon"};
  const EEVEE_EVOLUTION_DEX={vaporeon:134,jolteon:135,flareon:136};
  FAMILIES.vaporeon=family("Vaporeon","water","balanced",[60,6,9,1,1.5],stages(["Vaporeon",134,1,["water"]]),"Pistola Agua","ranged","");
  FAMILIES.jolteon=family("Jolteon","electric","balanced",[60,6,9,1,1.5],stages(["Jolteon",135,1,["electric"]]),"Impactrueno","ranged","");
  FAMILIES.flareon=family("Flareon","fire","balanced",[60,6,9,1,1.5],stages(["Flareon",136,1,["fire"]]),"Ascua","ranged","");
  const isEeveeEvolutionId=id=>EEVEE_EVOLUTION_IDS.includes(id);
  const eeveeEvolutionComplete=()=>EEVEE_EVOLUTION_IDS.every(id=>state?.owned?.includes(id));
  const eeveeOwnedEvolutionCount=()=>EEVEE_EVOLUTION_IDS.filter(id=>state?.owned?.includes(id)).length;
  const eeveeSharedCandy=id=>isEeveeEvolutionId(id)?Math.max(0,Number(state?.eeveeCandies||0)):Math.max(0,Number(state?.progress?.[id]?.candies||0));


