  function reconcileIllegalEquippedTMsRB(notify=true){
    if(!GEN1_TM_COMPAT_READY||!state?.progress)return[];
    state.tms=state.tms||{};const removed=[];
    for(const [id,p] of Object.entries(state.progress)){
      const loadout=tmLoadoutForProgress(p);let changed=false;
      for(let slot=0;slot<4;slot++){
        const tmId=loadout[slot];if(!tmId||!TMS[tmId])continue;
        if(!tmIsCompatible(tmId,id)||!tmSlotAcceptsTM(slot,tmId)||tmDuplicatesNaturalMove(tmId,id)){
          const st=ownedStage(id);state.tms[tmId]=true;
          removed.push({pokemon:st?.name||id,tm:TMS[tmId].name,slot:tmSlotLabel(slot)});loadout[slot]=null;changed=true;
        }
      }
      if(changed){p.tmLoadout=loadout;syncLegacyTMFields(p);}
    }
    if(removed.length){
      try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch(_){ }
      // V36.40.40 FIX · Durante el arranque esta auditoría puede ejecutarse antes de inicializar `logs`.
      // Si notify=false debe ser totalmente silenciosa; si notify=true, difiere el aviso hasta que el boot termine.
      if(notify)setTimeout(()=>{try{
        if(typeof addLog==="function")addLog(`🧬 Auditoría MT: ${removed.length} MT incompatible o repetida${removed.length===1?"":"s"} desequipada${removed.length===1?"":"s"}. Las MT siguen en tu colección.`);
        if(typeof toast==="function")toast(`🧬 ${removed.length} MT incompatible o repetida${removed.length===1?"":"s"} desequipada${removed.length===1?"":"s"} · no perdiste ninguna MT`);
      }catch(_){ }},0);
    }
    return removed;
  }
  async function loadGen1TMCompatibilityRB(){
    if(GEN1_TM_COMPAT_READY){reconcileIllegalEquippedTMsRB(false);return true;}
    if(GEN1_TM_COMPAT_LOADING)return false;GEN1_TM_COMPAT_LOADING=true;GEN1_TM_COMPAT_ERROR=false;
    try{
      const res=await fetch(GEN1_TM_COMPAT_SOURCE,{cache:"force-cache"});if(!res.ok)throw new Error(`HTTP ${res.status}`);
      const data=await res.json(),compat=buildGen1TMCompatRB(data);
      GEN1_TM_COMPAT_RB=compat;GEN1_TM_COMPAT_READY=true;GEN1_TM_COMPAT_ERROR=false;
      try{localStorage.setItem(GEN1_TM_COMPAT_CACHE_KEY,JSON.stringify({version:1,source:"Pokemon Red/Blue",compat}));}catch(_){ }
      reconcileIllegalEquippedTMsRB(true);
      setTimeout(()=>{try{renderCards();renderTMInventory();if(typeof inventoryTMDetailId!=="undefined"&&inventoryTMDetailId)renderTMEquipOverlay();}catch(_){ }},0);
      return true;
    }catch(err){GEN1_TM_COMPAT_ERROR=true;console.warn("No se pudo cargar compatibilidad MT R/B",err);setTimeout(()=>{try{renderTMInventory();}catch(_){ }},0);return false;}
    finally{GEN1_TM_COMPAT_LOADING=false;}
  }
  function movesFor(id){
    const tf=run?.team?.[id]?.transformData;
    if(id==="ditto"&&tf?.active&&Array.isArray(tf.moves)&&tf.moves.length)return tf.moves.map(m=>({...m,unlockStage:0,transformedCopy:true}));
    const base=baseMovesFor(id).map(m=>({...m})),p=state.progress?.[id],loadout=tmLoadoutForProgress(p);
    loadout.forEach((tmId,slot)=>{if(tmId&&TMS[tmId]&&tmIsCompatible(tmId,id)&&tmSlotAcceptsTM(slot,tmId)&&!tmDuplicatesNaturalMove(tmId,id))base[slot]={...TMS[tmId].move,tmId,unlockStage:0};});
    const finalStage=!!p&&isFinalEvolution(id);
    if(finalStage){
      const areaIndex=[2,1,0].find(i=>base[i]?.kind==="attack"&&!base[i]?.tmId);
      if(areaIndex!==undefined)base[areaIndex]={...base[areaIndex],area:true,areaFactor:.60,finalArea:true};
    }
    return base;
  }

