  function infiniteMilestoneNumber(meters){return Math.max(1,Math.round(Number(meters||0)/INFINITE_MILESTONE));}
  function infiniteFirstClearRates(milestoneMeters){
    const tier=infiniteMilestoneNumber(milestoneMeters),step=tier-1;
    const uncommon=Math.max(.05,.22-.018*step),epic=Math.min(.48,.28+.025*step),legendary=Math.min(.15,.02+.0125*step),rare=Math.max(.10,1-uncommon-epic-legendary);
    return {common:0,uncommon,rare,epic,legendary};
  }
  function infiniteRatesForMilestone(milestoneMeters){return infiniteFirstClearRates(milestoneMeters);}
  function nextInfiniteRewardMilestone(fromMeters=0){
    const claimed=new Set((state?.infiniteExpedition?.claimedMilestones||[]).map(Number));
    let milestone=(Math.floor(Math.max(0,Number(fromMeters||0))/INFINITE_MILESTONE)+1)*INFINITE_MILESTONE;
    while(claimed.has(milestone))milestone+=INFINITE_MILESTONE;
    return milestone;
  }
