      starter:{cashReward:2500},first_boss:{cashReward:5000},act1:{cashReward:15000},act2:{cashReward:25000},act3:{cashReward:40000},
      kanto_champion:{cashReward:75000,regionalPremiumTickets:1},route_10:{cashReward:20000,incenses:1},route_50:{cashReward:100000,regionalPremiumTickets:1,incenses:2},
