  function skillRank(id){
    const n=Number(state.skillTree?.[id]??0);
    return Number.isFinite(n)?n:0;
  }
  function skillUnlocked(id){const n=SKILL_NODES[id];return !!n&&n.requires.every(([r,k])=>skillRank(r)>=k);}
  const TREE_MAJOR_COSTS={c6:30000,c8:50000,c9:200000,f7:80000,f14:125000,f8:225000,e7:80000,e8:200000,a1:2500,a2:12500,a3:15000,a5:50000,a6:85000,a7:150000,a13:100000,a14:120000,a15:250000};
  if(window.PokeSendaRegionBoot?.isHoennClone&&SKILL_NODES.a3)SKILL_NODES.a3.desc="Incluido desde el inicio en Hoenn para acompañar su progresión más lenta. Repite automáticamente rutas normales; sigue desactivado en Expedición Infinita.";
  function skillCost(id){const n=SKILL_NODES[id],r=skillRank(id);if(Array.isArray(n.costs)&&n.costs.length)return Math.round(Number(n.costs[Math.min(r,n.costs.length-1)]||0));if(id==="trainer")return 1000;if(n?.max===1&&TREE_MAJOR_COSTS[id]!=null)return TREE_MAJOR_COSTS[id];const mult=n.branch==="automation"?6.40:6.00,growth=1.46;return Math.round(n.baseCost*mult*Math.pow(r+1,growth));}
  const ITEM_STACK_MAX=20;
  function isPotionItem(id){const it=ITEMS[id];return !!(it&&it.consumable&&!it.evolutionStone&&(it.healPct||it.curesStatus));}
  function isStoneItem(id){const it=ITEMS[id];return !!(it&&(it.evolutionStone||it.tradeOnly||it.resetMoves||it.incense));}
  function inventoryKindFor(id){return isPotionItem(id)?"potions":isStoneItem(id)?"stones":"main";}
  function inventoryCapacity(kind="main"){
    if(kind==="potions")return Infinity;
    if(kind==="stones")return Object.keys(ITEMS).filter(isStoneItem).length;
    return 20+2*skillRank("f9");
  }
  function inventorySlotsFor(items,kind="main"){
    return Object.entries(items||{}).reduce((a,[id,b])=>{const qty=Math.max(0,Number(b)||0),it=ITEMS[id];if(!it||qty<=0||inventoryKindFor(id)!==kind)return a;return a+1;},0);
  }
  function inventoryCount(kind="main"){return inventorySlotsFor(state.items,kind);}
  function inventoryEffectiveCapacity(kind="main",items=state.items){
    // Capacidad real fija. Un exceso heredado/DEV no amplía nunca el límite normal.
    return inventoryCapacity(kind);
  }
  function canStoreItem(itemId,amount=1){
    if(!ITEMS[itemId])return false;
    const add=Math.max(0,Number(amount)||0),have=Math.max(0,Number(state.items?.[itemId]||0)),kind=inventoryKindFor(itemId);
    if(kind==="potions")return true;
    if(have+add>ITEM_STACK_MAX)return false;
    if(have>0)return true;
    return inventoryCount(kind)<inventoryCapacity(kind);
  }
  function canSwapHeldItems(oldItem,newItem){
    const current={...(state.items||{})},test={...current};
    if(oldItem)test[oldItem]=Math.max(0,Number(test[oldItem]||0))+1;
    if(newItem)test[newItem]=Math.max(0,Number(test[newItem]||0)-1);
    for(const [id,qtyRaw] of Object.entries(test)){const qty=Math.max(0,Number(qtyRaw)||0);if(qty>0&&!isPotionItem(id)&&qty>ITEM_STACK_MAX)return false;}
    for(const kind of ["main","stones"]){const cap=inventoryCapacity(kind);if(Number.isFinite(cap)&&inventorySlotsFor(test,kind)>Math.max(cap,inventorySlotsFor(current,kind)))return false;}
    return true;
  }

