      if(qty<=0){delete state.items[id];changed=true;continue;}
      if(!isPotionItem(id)&&qty>ITEM_STACK_MAX){const extra=qty-ITEM_STACK_MAX;refund+=itemSellValue(id)*extra;excessUnits+=extra;qty=ITEM_STACK_MAX;changed=true;}
