  function markDexUnread(dex){dex=Number(dex);state.dexUnread=Array.isArray(state.dexUnread)?state.dexUnread:[];state.dexSeen=Array.isArray(state.dexSeen)?state.dexSeen:[];state.dexOwnedHistory=Array.isArray(state.dexOwnedHistory)?state.dexOwnedHistory:[];if(dex>=1&&dex<=REGION_DEX_MAX){const isNew=!state.dexOwnedHistory.includes(dex);if(!state.dexSeen.includes(dex))state.dexSeen.push(dex);if(isNew)state.dexOwnedHistory.push(dex);if(isNew&&!state.dexUnread.includes(dex))state.dexUnread.push(dex);state.dexSeen=[...new Set(state.dexSeen)].sort((a,b)=>a-b);state.dexOwnedHistory=[...new Set(state.dexOwnedHistory)].sort((a,b)=>a-b);}updateDexAlert();}
