  function routeState(){return isInfiniteMode()?state.infiniteExpedition:state.routes[state.currentRoute];}
  function checkpointUnlocked(meters,rs=routeState()){
    if(isInfiniteMode()||!rs)return Number(meters)===0;
    const m=Number(meters);
    if(m===0)return true;
    if(!POKEMON_CENTERS.includes(m))return false;
    if((rs.completions||0)>0)return true;
    return (Array.isArray(rs.centersSeen)&&rs.centersSeen.includes(m))||Number(rs.bestDistance||0)>=m||Number(rs.checkpoint||0)>=m;
  }
  function routeStartPoint(rs=routeState()){
    if(isInfiniteMode())return 0;
    if(!rs)return 0;
    const farm=rs.farmCheckpoint;
    if(farm!==null&&farm!==undefined&&[0,2500,5000,7500].includes(Number(farm))&&checkpointUnlocked(Number(farm),rs))return Number(farm);
    return Math.max(0,Number(rs.checkpoint||0));
  }
