    return a.map(([itemId,name])=>{const qty=Number(state.items[itemId]||0),item=ITEMS[itemId];return `<div class="evo-status-card stone"><span class="evo-status-tag">RAMA</span><span class="evo-status-main"><small>Clamperl puede evolucionar a</small><b>${name}</b></span><span class="evo-status-req"><button type="button" class="evo-stone-quick ${qty>0?"owned":"missing"}" data-stone-evolve="clamperl" data-stone-item="${itemId}" title="Evolucionar a ${name} con ${item?.name||itemId}">🐚 <b>${item?.name||itemId}</b><span class="stone-count">×${qty}</span></button></span></div>`;}).join("");
