    const infiniteText=infiniteUnlocked()?` · ♾ Récord: ${formatMeters(state.infiniteExpedition?.bestDistance||0)}`:"";
    $("menuSaveInfo").textContent=state.starter?`Pokédex: ${pokedexDiscoveredCount()}/${pokedexTotalCount()} · Logros: ${achievementUnlockedCount()}/${ACHIEVEMENTS.length} · ₽${Math.floor(state.pokedollars||0).toLocaleString("es-CL")} · Poké Balls: ${state.totalChests||0} · Rutas completadas: ${completed}${infiniteText}`:"Partida nueva";
