    state=freshState();state.trainerAvatar=keepTrainerAvatar;state.pokesendaWelcomeSeen=keepWelcomeSeen;state.options.musicVolume=keepMusicVolume;state.options.musicTrack=MUSIC_TRACKS[keepMusicTrack]?keepMusicTrack:"classic_menu";state.options.musicPlaylist=true;state.options.sfxVolume=keepSfxVolume;state.starter=id;startMusic();state.owned=[id];state.progress[id]=freshPokemonProgress(1,"rare");state.progress[id].moveRanks=baseMovesFor(id).map(m=>(m.kind==="support"||(m.unlockStage||0)<=0)?1:0);state.formation=[id,null,null,null,null,null];state.dexSeen=Array.isArray(state.dexSeen)?state.dexSeen:[];if(!state.dexSeen.includes(FAMILIES[id].stages[0].dex))state.dexSeen.push(FAMILIES[id].stages[0].dex);markDexUnread(FAMILIES[id].stages[0].dex);
