  function starterRewardForRoute(routeId){
    const chosen=state.starter;if(!chosen)return null;
    const hoenn=!!window.PokeSendaRegionBoot?.isHoennClone;
    const weak=hoenn?{treecko:"mudkip",torchic:"treecko",mudkip:"torchic"}:{bulbasaur:"squirtle",charmander:"bulbasaur",squirtle:"charmander"};
    const strong=hoenn?{treecko:"torchic",torchic:"mudkip",mudkip:"treecko"}:{bulbasaur:"charmander",charmander:"squirtle",squirtle:"bulbasaur"};
    if(routeId==="route1")return chosen;if(routeId==="route2")return weak[chosen];if(routeId==="route3")return strong[chosen];return null;
  }
  // V36.40.89 · Cueva Rocosa usa una distribución total por rareza para evitar que
  // tener muchas familias Raras infle artificialmente su probabilidad conjunta.
  // Se mantienen exactamente las mismas familias; solo cambia cómo se reparte el peso.
  const ROUTE2_GACHA_RARITY_CHANCE={common:.43,uncommon:.46,rare:.105,epic:.0045,legendary:.0005};
  // Hoenn · probabilidad LEGENDARIA TOTAL por ruta, alineada con el balance regional actual.
  // Las 4 especies legendarias/singulares de cada Gachapon comparten este porcentaje total.
  const HOENN_LEGENDARY_RATE_BY_ROUTE={route1:.0002,route2:.0002,route3:.0001}; // 0,02% · 0,02% · 0,01%
  function normalizeGachaPoolByRarity(pool,targets){
    const out=(pool||[]).map(x=>({...x})),groups={};
    for(const x of out)(groups[x.rarity]||(groups[x.rarity]=[])).push(x);
    for(const [rarity,items] of Object.entries(groups)){
      const target=Math.max(0,Number(targets?.[rarity]||0));
      const per=items.length?target/items.length:0;
      for(const x of items)x.weight=per;
    }
    return out;
  }
  function normalizeLegendaryPoolShare(pool,targetRate){
    const out=(pool||[]).map(x=>({...x})),legends=out.filter(x=>x.rarity==='legendary');
    targetRate=Math.max(0,Math.min(.999999,Number(targetRate)||0));
    if(!legends.length||targetRate<=0)return out;
    const nonLegend=out.filter(x=>x.rarity!=='legendary').reduce((sum,x)=>sum+Math.max(0,Number(x.weight)||0),0);
    const currentLegend=legends.reduce((sum,x)=>sum+Math.max(0,Number(x.weight)||0),0);
    if(nonLegend<=0||currentLegend<=0)return out;
    const wantedLegendWeight=nonLegend*targetRate/(1-targetRate),scale=wantedLegendWeight/currentLegend;
    for(const x of out)if(x.rarity==='legendary')x.weight=Math.max(0,Number(x.weight)||0)*scale;
    return out;
  }
  // V36.68 · Pokédex de ruta progresiva por profundidad.
  // Las Poké Balls normales ya no exponen el pool completo desde el primer jefe:
  // km 1–3 = tercio temprano, km 4–6 = dos tercios, km 7–9 = familias regulares completas,
  // km 10 = pool completo + familias especiales/Legendarias. El inicial raro del acto sigue disponible.
  function routeGachaDepthTier(km=1){km=Math.max(1,Math.min(10,Math.floor(Number(km)||1)));return km<=3?1:km<=6?2:km<=9?3:4;}
  function progressiveRouteGachaPool(routeId,km,pool){
    const route=ROUTES[routeId];if(!route||!Array.isArray(pool))return pool||[];
    const tier=routeGachaDepthTier(km);if(tier>=4)return pool.map(x=>({...x}));
    const fullIds=new Set(pool.map(x=>x.id)),regular=[];
    for(const id of route.enemies||[])if(fullIds.has(id)&&!regular.includes(id))regular.push(id);
    // Fallback defensivo: si una ruta futura no declara enemigos, progresamos todos los no legendarios.
    if(!regular.length)for(const x of pool)if(x.rarity!=="legendary"&&!regular.includes(x.id))regular.push(x.id);
    const limit=tier===1?Math.ceil(regular.length/3):tier===2?Math.ceil(regular.length*2/3):regular.length;
    const allowed=new Set(regular.slice(0,limit));
    return pool.filter(x=>allowed.has(x.id));
  }
  function routeGachaDepthLabel(km=1){const tier=routeGachaDepthTier(km);return tier===1?"Pool temprano · km 1–3":tier===2?"Pool intermedio · km 4–6":tier===3?"Pool avanzado · km 7–9":"Pool completo · km 10";}
  function rewardPoolFor(routeId,km=1){
    if(routeId===INFINITE_ROUTE_ID){const starters=window.PokeSendaRegionBoot?.isHoennClone?["treecko","torchic","mudkip"]:["bulbasaur","charmander","squirtle"],ids=[...new Set([...Object.keys(GACHA_RARITY),...starters].filter(id=>FAMILIES[id]))];return ids.map(id=>{const rarity=captureFamilyRarity(id);return{id,rarity,weight:GACHA_WEIGHT[rarity]||1};});}
    let pool=ROUTES[routeId].gacha.map(x=>({...x}));
    pool=progressiveRouteGachaPool(routeId,km,pool);
    const starter=starterRewardForRoute(routeId);
    if(starter&&!pool.some(x=>x.id===starter))pool.push({id:starter,rarity:"rare",weight:1.5,dynamicStarter:true});
    if(routeId==="route2")pool=normalizeGachaPoolByRarity(pool,ROUTE2_GACHA_RARITY_CHANCE);
    if(window.PokeSendaRegionBoot?.isHoennClone){
      const target=HOENN_LEGENDARY_RATE_BY_ROUTE[routeId];
      if(target!=null)pool=normalizeLegendaryPoolShare(pool,target);
    }
    return pool;
  }
  function poolPercentages(routeId,km){
    const pool=rewardPoolFor(routeId,km),total=pool.reduce((s,x)=>s+x.weight,0);
    return pool.map(x=>({...x,pct:x.weight/total*100}));
  }
  window.PokeSendaGachaPoolQA=()=>{const rows=[];for(const routeId of ["route1","route2","route3"]){if(!ROUTES[routeId])continue;for(const km of [1,4,7,10]){const pool=rewardPoolFor(routeId,km),premium=timedGachaPool();rows.push({region:window.PokeSendaRegionBoot?.isHoennClone?"hoenn":"kanto",routeId,km,normalFamilies:new Set(pool.map(x=>x.id)).size,premiumFamilies:new Set(premium.map(x=>x.id)).size});}}return rows;};
  window.PokeSendaHoennGachaQA=()=>{
    if(!window.PokeSendaRegionBoot?.isHoennClone)return {active:false,reason:'Ejecuta la QA con Hoenn activo.'};
    const finalChecks=[['route1',10,.0002],['route2',10,.0002],['route3',10,.0001]].map(([routeId,km,target])=>{
      const pool=rewardPoolFor(routeId,km),total=pool.reduce((n,x)=>n+Math.max(0,Number(x.weight)||0),0),legendary=pool.filter(x=>x.rarity==='legendary').reduce((n,x)=>n+Math.max(0,Number(x.weight)||0),0),actual=total>0?legendary/total:0;
      return {routeId,km,target,actual,percent:Number((actual*100).toFixed(6)),legendaryEntries:pool.filter(x=>x.rarity==='legendary').length,ok:Math.abs(actual-target)<1e-10};
    });
    const depthChecks=[];
    for(const routeId of ['route1','route2','route3'])for(let km=1;km<=9;km++){
      const pool=rewardPoolFor(routeId,km),legendaryEntries=pool.filter(x=>x.rarity==='legendary').length;
      depthChecks.push({routeId,km,tier:routeGachaDepthTier(km),legendaryEntries,ok:legendaryEntries===0});
    }
    const sizeChecks=['route1','route2','route3'].map(routeId=>{const sizes=[1,4,7,10].map(km=>rewardPoolFor(routeId,km).filter(x=>!x.dynamicStarter).length);return{routeId,sizes,ok:sizes[0]<sizes[1]&&sizes[1]<sizes[2]&&sizes[2]<sizes[3]};});
    return {active:true,finalChecks,depthChecks,sizeChecks,tiers:{km1_3:1,km4_6:2,km7_9:3,km10:4},ok:finalChecks.every(x=>x.ok)&&depthChecks.every(x=>x.ok)&&sizeChecks.every(x=>x.ok)};
  };
  function renderRouteInfo(){if(pkBackgroundCatchingUp)return;
    const route=ROUTES[state.currentRoute],base=run?run.distance:routeStartPoint();
    if(isInfiniteMode()){
      const inf=state.infiniteExpedition||{},pending=(inf.pendingReward&&inf.pendingReward.firstClear)?inf.pendingReward:null,nextMilestone=pending?.milestone||nextInfiniteRewardMilestone(base),rates=pending?.rates||infiniteRatesForMilestone(nextMilestone),tier=infiniteMilestoneNumber(nextMilestone);
      $("routeDescription").innerHTML=`<div class="infinite-record-card"><div class="infinite-record-grid"><div class="infinite-record-metric"><b>${formatMeters(inf.bestDistance||0)}</b><small>récord permanente</small></div><div class="infinite-record-metric"><b>${inf.claimedMilestones?.length||0}</b><small>hitos nuevos reclamados</small></div><div class="infinite-record-metric"><b>${inf.totalRuns||0}</b><small>intentos iniciados</small></div></div></div><span class="infinite-badge">♾ Próximo premio · Hito ${tier} · ${formatMeters(nextMilestone)}</span> · Gachapon mejorado de récord. Cada hito de 10.000 m entrega su Gachapon una sola vez: si ya lo reclamaste, al volver a pasar por él no aparece nada y continúas directamente hacia el siguiente hito nuevo. Siempre comienzas desde 0 m. No hay Centros Pokémon ni eventos de ruta; hay jefe cada 1.000 m. No se obtienen Pokédólares directos en este modo. La dificultad aumenta sin límite, pero la entrada comienza alrededor de Nv.22–25 y escala de forma progresiva.`;
      const order=["common","uncommon","rare","epic","legendary"],names={common:"Común",uncommon:"Poco común",rare:"Raro",epic:"Épico",legendary:"Legendario"};
      $("poolList").innerHTML=order.map(r=>`<div class="pool-item"><span>${names[r]} ${rarityBadge(r)}</span><span>${(rates[r]*100)<1?(rates[r]*100).toFixed(2):(rates[r]*100).toFixed(1)}%</span></div>`).join("")+(pending?`<button class="btn warn" data-open-infinite-pending style="grid-column:1/-1;margin-top:7px">🎁 Abrir recompensa pendiente de ${formatMeters(pending.milestone)}</button>`:"");
      const btn=$("poolList").querySelector("[data-open-infinite-pending]");if(btn)btn.addEventListener("click",openInfinitePendingReward);return;
    }
    const km=Math.max(1,Math.min(10,Math.floor(base/1000)+1));
    const repeatNote=(routeState().completions||0)>0?` · Repetición: rivales normales entregan 35% de Pokédólares y jefes 50%. Punto de farmeo: ${formatMeters(routeStartPoint())}; con Auto-repetir se recorre siempre desde ahí hasta 10.000 m.`:"";
    const hoenn=!!window.PokeSendaRegionBoot?.isHoennClone;
    const hoennPaceNote=hoenn?` · Ritmo Hoenn: EXP de combate al ${Math.round(HOENN_XP_EARN_MULT*100)}% y Pokédólares regionales al ${Math.round(HOENN_MONEY_EARN_MULT*100)}% de la base. Auto-repetir está disponible desde el inicio.`:"";
    const gachaBalanceNote=hoenn
      ?(km<10?" · Legendarios de ruta: bloqueados hasta el jefe de 10.000 m.":state.currentRoute==="route1"||state.currentRoute==="route2"?" · Legendarios: 0,02% total en el pool completo del km 10 antes de bonus del Entrenador.":state.currentRoute==="route3"?" · Legendarios: 0,01% total en el pool completo del km 10 antes de bonus del Entrenador.":"")
      :(state.currentRoute==="route2"&&km===10?" · Gachapon completo equilibrado por rareza: 43% Común · 46% Poco común · 10,5% Raro · 0,45% Épico · 0,05% Legendario antes de bonus del Entrenador.":km<10?" · Las familias especiales y Legendarias se reservan para el km 10.":"");
    const depthNote=` · Captura progresiva: ${routeGachaDepthLabel(km)}. El pool se amplía al llegar a los km 4, 7 y 10.`;
    $("routeDescription").textContent=route.description+(state.currentRoute==="route1"&&km===1?" · Primer kilómetro: rivales solo Normal/Bicho.":"")+` · Nivel recomendado: ${route.recommended||"—"}. · Jefe final: Nv.${route.finalBossLevel||25}. · Inicial raro del acto: ${FAMILIES[starterRewardForRoute(state.currentRoute)]?.stages[0].name||"—"}. · Pokédex regional completa entre capturas y evoluciones. · IA aliada: prioriza efectividad, potencia, defensa rival y uso situacional de Support. · Capturas: nivel adaptado al acto, posibilidad de encontrar formas base/evolucionadas y probabilidad Shiny base de 1/1.536 por tirada, mejorable de forma moderada por el Árbol y la Pokédex completa.${depthNote}${gachaBalanceNote}${hoennPaceNote}${repeatNote}`;
    $("poolList").innerHTML=poolPercentages(state.currentRoute,km).map(x=>{const name=FAMILIES[x.id].stages[0].name,pct=x.pct<.01?x.pct.toFixed(3):x.pct<1?x.pct.toFixed(2):x.pct.toFixed(1);return `<div class="pool-item"><span>${name} ${rarityBadge(x.rarity)}</span><span>${pct}%</span></div>`;}).join("");
  }

