    const checkpointDisplay=inf?"0 m":formatMeters(run?run.checkpoint:routeStartPoint(rs));if($("checkpointBtnValue"))$("checkpointBtnValue").textContent=checkpointDisplay;const mtG=ensureMTGachaState();if($("mtTicketsTop"))$("mtTicketsTop").textContent=String(mtG.tickets);if($("mtTicketTop"))$("mtTicketTop").classList.toggle("has-tickets",mtG.tickets>0);$("collectionTop").textContent=`${pokedexDiscoveredCount()}/${pokedexTotalCount()}`;$("moneyTop").textContent=`₽${Math.floor(state.pokedollars||0).toLocaleString("es-CL")}`;if($("pcBoxCountTop"))$("pcBoxCountTop").textContent=String((state.owned||[]).length);
    const cpBtn=$("checkpointSelectBtn");if(cpBtn){cpBtn.classList.toggle("hidden",inf);cpBtn.disabled=inf||!!run;cpBtn.title=run?"Pausa o termina la expedición para cambiar el punto de inicio":"Elegir Inicio o un Centro Pokémon ya desbloqueado";}
