  function currentPossessionByDex(dex){dex=Number(dex);for(const id of state.owned||[]){const fam=FAMILIES[id],p=state.progress?.[id];if(!fam||!p)continue;const idx=Math.max(0,Math.min(fam.stages.length-1,Number(p.stageIndex||0))),st=fam.stages[idx];if(st?.dex===dex)return{id,p,stage:st};}return null;}
