  function normalizedSearch(s){return String(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim();}
  const PC_RARITY_ORDER={common:0,uncommon:1,rare:2,epic:3,legendary:4};
  function boxPowerScore(id){
    const p=state.progress?.[id],st=p&&FAMILIES[id]?ownedStage(id):null;if(!p||!st)return 0;
    const stars=Math.max(1,Math.min(5,Number(p.stars||1))),core=baseCombatForStage(st,p.level,p.nature),master=skillRank("c9")?1.05:1,statMult=(1+.10*(stars-1))*master,speedMult=(1+.025*(stars-1))*(1+.005*skillRank("c3"))*master;
    let hp=core.maxHp*statMult*(1+.009*skillRank("c2")),atk=core.atk*statMult*(1+.009*skillRank("c1")),spAtk=core.spAtk*statMult*(1+.009*skillRank("c1")),def=core.def*statMult,spDef=core.spDef*statMult,cd=core.cd/speedMult,crit=.05+.01*(stars-1)+.002*skillRank("c4"),reduction=Math.min(.35,.0035*skillRank("c5")+.0035*skillRank("e9"));
    const item=equippedItem(id);if(item&&isItemCompatible(p.heldItem,id)){if(item.hp)hp*=1+item.hp;if(item.atk){atk*=1+item.atk;spAtk*=1+item.atk;}if(item.physicalAtk)atk*=1+item.physicalAtk;if(item.speed){if(item.speed>0)cd/=1+item.speed;else cd*=1+Math.abs(item.speed);}if(item.crit)crit+=item.crit;}
    const score=hp*.42+(atk+spAtk)*6.4+(def+spDef)*1.15+(1/Math.max(.25,cd))*125+Math.max(0,crit)*180+Math.max(0,reduction)*260;
    return Math.max(1,Math.round(finiteNumber(score,1)));
  }
  function pcEntryCompare(a,b){
    let cmp=0;
    if(pcBoxSort==="name")cmp=a.st.name.localeCompare(b.st.name,"es",{sensitivity:"base"});
    else if(pcBoxSort==="level")cmp=Number(a.p.level||1)-Number(b.p.level||1);
    else if(pcBoxSort==="stars")cmp=Number(a.p.stars||1)-Number(b.p.stars||1);
    else if(pcBoxSort==="rarity")cmp=(PC_RARITY_ORDER[a.rarity]??0)-(PC_RARITY_ORDER[b.rarity]??0);
    else if(pcBoxSort==="type")cmp=displayType(a.st.types?.[0]||"").localeCompare(displayType(b.st.types?.[0]||""),"es",{sensitivity:"base"});
    else if(pcBoxSort==="power")cmp=Number(a.power||0)-Number(b.power||0);
    else cmp=Number(a.st.dex||0)-Number(b.st.dex||0);
    if(cmp===0)cmp=Number(a.st.dex||0)-Number(b.st.dex||0);
    return pcBoxSortDir==="desc"?-cmp:cmp;
  }
