    const entries=(state.owned||[]).filter(id=>FAMILIES[id]&&state.progress[id]).map(id=>{const p=state.progress[id],st=ownedStage(id),held=p.heldItem&&ITEMS[p.heldItem]?ITEMS[p.heldItem]:null;return{id,p,st,held,inTeam:formationSet.has(id),rarity:familyRarity(id),power:boxPowerScore(id)};});
