      if(!q)return true;const hay=normalizedSearch(`${x.st.name} ${x.st.types.map(displayType).join(" ")} nivel ${x.p.level} nv ${x.p.level} ${RARITIES[x.rarity]?.name||""} poder ${x.power}`);return hay.includes(q);
