    $("pcBoxOwnedCount").textContent=String(entries.length);$("pcBoxFormationCount").textContent=String(teamCount);$("pcBoxStoredCount").textContent=String(boxCount);$("pcBoxSearchCount").textContent=`${shown.length}/${entries.length}`;if($("pcBoxCountTop"))$("pcBoxCountTop").textContent=String(entries.length);
    document.querySelectorAll("[data-pc-status]").forEach(b=>b.classList.toggle("active",b.dataset.pcStatus===pcBoxStatusFilter));document.querySelectorAll("[data-pc-rarity]").forEach(b=>b.classList.toggle("active",b.dataset.pcRarity===pcBoxRarityFilter));updatePcBoxSortControls();
