      return `<button class="pc-swap-choice empty ${current?"selected":""}" data-formation-swap-slot="${index}" ${current?"disabled":""}><span class="pc-swap-slot">${slotLabel}</span><div style="font-size:34px;text-align:center;color:#6f8498">＋</div><span><b>${current?"✓ ":""}Hueco libre</b><small>${current?"Posición actual":"Mover aquí"}</small></span></button>`;
