    const boxOverlayEl=$("pcBoxOverlay"),boxModal=boxOverlayEl?.querySelector(".pc-box-modal"),boxWasOpen=!!boxOverlayEl&&!boxOverlayEl.classList.contains("hidden"),boxScroll=boxModal?.scrollTop||0;
