  function baseCollectibleFamilyIds(){return Object.keys(FAMILIES).filter(id=>!isEeveeEvolutionId(id));}
  function capturedBaseFamilyCount(){const seen=new Set(state.dexSeen||[]);return baseCollectibleFamilyIds().filter(id=>(FAMILIES[id]?.stages||[]).some(st=>seen.has(st.dex))).length;}
  function pokedexTotalCount(){if(window.PokeSendaRegionBoot?.isHoennClone){const s=new Set();for(const f of Object.values(FAMILIES))for(const st of (f?.stages||[]))s.add(Number(st.dex));return s.size;}return 151;}
  function pokedexDiscoveredCount(){return new Set((state.dexSeen||[]).map(Number).filter(x=>x>=1&&x<=REGION_DEX_MAX)).size;}
  function pokedexRouteFamilySet(routeId){
    if(!routeId||routeId==="all")return null;
    return new Set(achievementRouteIds(routeId));
  }
  // V36.59.2 · Los contadores de zona de la Pokédex cuentan especies, no familias.
  // Cada familia del pool aporta todas sus formas evolutivas y cada N.º Pokédex cuenta una sola vez.
  function pokedexRouteDexSet(routeId){
    const dexes=new Set();
    for(const id of achievementRouteIds(routeId)){
      for(const st of (FAMILIES[id]?.stages||[])){
        const dex=Number(st?.dex);if(dex>=1&&dex<=REGION_DEX_MAX)dexes.add(dex);
      }
    }
    return dexes;
  }
  function updatePokedexRouteProgress(){
    const defs=[["route1","pokedexRoute1Count"],["route2","pokedexRoute2Count"],["route3","pokedexRoute3Count"]],seen=new Set((state.dexSeen||[]).map(Number));
    for(const [routeId,elementId] of defs){
      const el=$(elementId);if(!el)continue;
      const routeDex=pokedexRouteDexSet(routeId),total=routeDex.size,registered=[...routeDex].filter(dex=>seen.has(dex)).length;
      el.textContent=`${registered}/${total}`;
      el.parentElement?.setAttribute("title",`${ROUTES[routeId].name}: ${registered} de ${total} Pokémon registrados · incluye evoluciones`);
    }
  }
  function renderPokedex(){if(pkBackgroundCatchingUp)return;
    const wrap=$("pokedexGrid");if(!wrap)return;const pkOldDexSprites=pkCaptureStablePokemonImgs(wrap);
    const entries=[],dexSeen=new Set(state.dexSeen||[]),q=normalizedSearch($("pokedexSearch")?.value||""),routeFamilies=pokedexRouteFamilySet(pokedexRouteFilter);
    for(const [id,fam] of Object.entries(FAMILIES)){
      if(isEeveeEvolutionId(id))continue;
      fam.stages.forEach((st,idx)=>{
        const discovered=dexSeen.has(st.dex),possession=currentPossessionByDex(st.dex),rarity=rarityForStage(id,idx),isNew=discovered&&(state.dexUnread||[]).includes(st.dex),status=possession?"owned":discovered?"registered":"locked",hasShiny=(state.shinyDex||[]).includes(st.dex);
        entries.push({id,st,idx,discovered,possession,rarity,isNew,status,hasShiny});
      });
    }
    if(!window.PokeSendaRegionBoot?.isHoennClone)entries.sort((a,b)=>a.st.dex-b.st.dex);
    const routeEntries=routeFamilies?entries.filter(x=>routeFamilies.has(x.id)):entries;
    const shown=routeEntries.filter(x=>{
      if(pokedexStatusFilter==="new"){if(!x.isNew)return false;}
      else if(pokedexStatusFilter==="shiny"){if(!x.hasShiny)return false;}
      else if(pokedexStatusFilter!=="all"&&x.status!==pokedexStatusFilter)return false;
      if(pokedexRarityFilter!=="all"&&(!x.discovered||x.rarity!==pokedexRarityFilter))return false;
      if(!q)return true;
      const hay=normalizedSearch(`${x.st.name} ${x.st.dex} ${x.st.types.map(displayType).join(" ")} ${RARITIES[x.rarity]?.name||""}`);
      return hay.includes(q);
    });
    wrap.innerHTML=shown.map(x=>{
      const {id,st,idx,discovered,possession,rarity,isNew,hasShiny}=x,status=possession?'<span class="dex-possession-badge owned">EN POSESIÓN</span>':discovered?'<span class="dex-possession-badge registered">REGISTRADO</span>':"",showShiny=hasShiny&&dexUsesShinyView(st.dex);
      return `<div class="dex-card ${discovered?`discovered rarity-${rarity}`:"locked"} ${possession?"current-possession":""} ${hasShiny?"has-shiny":""}" ${discovered?`data-dex-family="${id}" data-stage-index="${idx}" data-dex="${st.dex}"`:""}>${isNew?'<span class="dex-new-badge" title="Entrada nueva">!</span>':""}<span class="dex-number">#${String(st.dex).padStart(3,"0")}</span><img data-pk-sprite-key="dex-main-${st.dex}-${showShiny?1:0}" data-pk-png="${pokemonStaticSpriteUrl(st.dex,showShiny)}" data-pk-gif-done="1" src="${pokemonAnimatedSpriteUrl(st.dex,false,showShiny)}" alt="${discovered?st.name:"???"}">${hasShiny?`<img class="dex-shiny-mini" data-pk-sprite-key="dex-mini-${st.dex}-${showShiny?0:1}" data-pk-png="${pokemonStaticSpriteUrl(st.dex,!showShiny)}" data-pk-gif-done="1" src="${pokemonAnimatedSpriteUrl(st.dex,false,!showShiny)}" alt="${st.name} ${showShiny?"normal":"Shiny"}"><span class="dex-shiny-badge" title="${showShiny?"Vista Shiny activa":"Variante Shiny registrada"}">★</span>`:""}<div class="dex-name">${discovered?st.name:"???"}</div><div class="dex-meta">${discovered?st.types.map(displayType).join("/"):"No descubierto"}</div><div class="dex-rarity-row">${discovered?rarityBadge(rarity):""}</div>${status}</div>`;
    }).join("")||'<div class="pc-box-empty">No hay entradas que coincidan con estos filtros.</div>';
    pkRestoreStablePokemonImgs(wrap,pkOldDexSprites);
    $("pokedexCaught").textContent=`${pokedexDiscoveredCount()} / ${pokedexTotalCount()}`;
    if($("pokedexNewCount"))$("pokedexNewCount").textContent=String((state.dexUnread||[]).length);
    $("pokedexOwned").textContent=String(currentOwnedDexCount());
    $("pokedexFamilies").textContent=`${capturedBaseFamilyCount()} / ${baseCollectibleFamilyIds().length}`;
    if($("pokedexShiny"))$("pokedexShiny").textContent=`${shinyDexCount()}/${pokedexTotalCount()}`;
    if($("pokedexFilterCount"))$("pokedexFilterCount").textContent=`${shown.length}/${routeEntries.length}`;
    updatePokedexRouteProgress();
    document.querySelectorAll("[data-dex-status]").forEach(b=>b.classList.toggle("active",b.dataset.dexStatus===pokedexStatusFilter));
    document.querySelectorAll("[data-dex-rarity]").forEach(b=>b.classList.toggle("active",b.dataset.dexRarity===pokedexRarityFilter));
    document.querySelectorAll("[data-dex-route]").forEach(b=>b.classList.toggle("active",(b.dataset.dexRoute||"all")===pokedexRouteFilter));
    wrap.querySelectorAll("[data-dex]").forEach(el=>el.addEventListener("click",()=>openDexLore(Number(el.dataset.dex),el.dataset.dexFamily,Number(el.dataset.stageIndex))));
    updateDexAlert();
  }
  function openPokedex(){
    pokedexStatusFilter="all";pokedexRarityFilter="all";pokedexRouteFilter="all";
    if($("pokedexSearch"))$("pokedexSearch").value="";
    renderPokedex();$("pokedexOverlay").classList.remove("hidden");updateDexAlert();
  }
