  function achievementUnlockedCount(){state.achievements=normalizeAchievementState(state.achievements);return ACHIEVEMENTS.filter(a=>state.achievements.unlocked[a.id]).length;}
  function achievementPointsEarned(){state.achievements=normalizeAchievementState(state.achievements);return ACHIEVEMENTS.reduce((n,a)=>n+(state.achievements.unlocked[a.id]?Number(a.points||0):0),0);}
  function achievementPointsTotal(){return ACHIEVEMENTS.reduce((n,a)=>n+Number(a.points||0),0);}
  function achievementClaimableCashDefs(){state.achievements=normalizeAchievementState(state.achievements);const claimed=new Set(state.achievements.claimedRewards);return ACHIEVEMENTS.filter(a=>state.achievements.unlocked[a.id]&&!claimed.has(a.id));}
  function achievementClaimableMilestones(){state.achievements=normalizeAchievementState(state.achievements);const pts=achievementPointsEarned(),claimed=new Set(state.achievements.claimedMilestones);return ACHIEVEMENT_MILESTONES.filter(m=>pts>=m.points&&!claimed.has(m.id));}
  function updateAchievementAlert(){
    if(!state?.achievements)return;state.achievements=normalizeAchievementState(state.achievements);const n=state.achievements.unread.length+achievementClaimableCashDefs().length+achievementClaimableMilestones().length;
    for(const id of ["achievementAlert","menuAchievementAlert"]){const el=$(id);if(!el)continue;el.classList.toggle("hidden",!n);el.textContent=n>9?"9+":"!";el.title=n?`${n} novedad${n===1?"":"es"} o recompensa${n===1?"":"s"} pendiente${n===1?"":"s"} en Logros`:"";}
  }
  function achievementMilestoneRewardText(m){const parts=[];if(m.master)parts.push("Amuleto Maestro");if(m.money)parts.push(`₽${achievementMilestoneMoney(m).toLocaleString("es-CL")}`);if(m.tickets)parts.push(`${m.tickets} Ticket${m.tickets===1?"":"s"} Premium`);if(m.shinyTickets)parts.push(`${m.shinyTickets} Ticket${m.shinyTickets===1?"":"s"} Shiny`);if(m.johtoShinyTickets)parts.push(`${m.johtoShinyTickets} Tickets Shiny para Johto`);if(m.futureRegionShinyTickets)parts.push(`${m.futureRegionShinyTickets} Tickets Shiny reservados para la próxima región`);if(m.johtoPremiumTickets)parts.push(`${m.johtoPremiumTickets} Tickets Premium para Johto`);if(m.futureRegionPremiumTickets)parts.push(`${m.futureRegionPremiumTickets} Tickets Premium reservados para la próxima región`);if(m.randomMints)parts.push(`${m.randomMints} Menta${m.randomMints===1?"":"s"} aleatoria${m.randomMints===1?"":"s"}`);if(m.masterMints)parts.push(`${m.masterMints} Menta${m.masterMints===1?"":"s"} Maestra${m.masterMints===1?"":"s"}`);if(m.incenses)parts.push(`${m.incenses} Incienso${m.incenses===1?"":"s"} aleatorio${m.incenses===1?"":"s"}`);return parts.join(" + ")||m.desc;}
  const CROSS_REGION_REWARD_KEY="pokesenda_cross_region_rewards_v1";
  const JOHTO_ACHIEVEMENT_SAVE_KEY="pokesenda_johto_dev_isolated_v1";
  function grantJohtoPremiumTicketsFromKanto(amount,sourceId){
    amount=Math.max(0,Math.floor(Number(amount)||0));if(!amount)return 0;sourceId=String(sourceId||"");
    try{
      const raw=localStorage.getItem(JOHTO_ACHIEVEMENT_SAVE_KEY);
      if(raw){
        const js=JSON.parse(raw)||{};
        js.achievements=js.achievements&&typeof js.achievements==="object"?js.achievements:{};
        js.achievements.premiumTickets=Math.max(0,Math.floor(Number(js.achievements.premiumTickets||0)));
        js.crossRegionRewards=js.crossRegionRewards&&typeof js.crossRegionRewards==="object"?js.crossRegionRewards:{claimedKantoAchievements:[]};
        const claimed=Array.isArray(js.crossRegionRewards.claimedKantoAchievements)?js.crossRegionRewards.claimedKantoAchievements:[];
        if(sourceId&&claimed.includes(sourceId))return 0;
        js.achievements.premiumTickets+=amount;
        if(sourceId)claimed.push(sourceId);
        js.crossRegionRewards.claimedKantoAchievements=[...new Set(claimed)];
        localStorage.setItem(JOHTO_ACHIEVEMENT_SAVE_KEY,JSON.stringify(js));
        return amount;
      }
    }catch(_){}
    try{
      const q=JSON.parse(localStorage.getItem(CROSS_REGION_REWARD_KEY)||"{}");
      q.johtoPremiumTickets=Math.max(0,Math.floor(Number(q.johtoPremiumTickets||0)));
      q.claimedKantoAchievements=Array.isArray(q.claimedKantoAchievements)?q.claimedKantoAchievements:[];
      if(sourceId&&q.claimedKantoAchievements.includes(sourceId))return 0;
      q.johtoPremiumTickets+=amount;
      if(sourceId)q.claimedKantoAchievements.push(sourceId);
      q.claimedKantoAchievements=[...new Set(q.claimedKantoAchievements)];
      localStorage.setItem(CROSS_REGION_REWARD_KEY,JSON.stringify(q));
      return amount;
    }catch(_){return 0;}
  }
