    const plan=moveResetPlan(pokemonId);if(plan.refund<=0){toast(`${st.name} no tiene puntos invertidos para recuperar`);return;}
    const ok=await gameConfirm({title:"Orbe de Reaprendizaje · Nv.60",message:`${st.name} consiguió esta oportunidad al alcanzar el nivel máximo.\n\nSe reiniciarán sus rangos de movimiento y recuperarás ${plan.refund} punto${plan.refund===1?"":"s"} para repartirlos otra vez.\n\nEste Orbe es personal, se usa una sola vez y NO consume el Orbe de Reaprendizaje del Inventario. Nivel, estrellas, evolución, MT, naturaleza y objeto equipado no cambian.`,confirmText:"Reaprender",cancelText:"Guardar Orbe",tone:"warning",symbol:"🔮"});if(!ok)return;
    p.moveRanks=plan.baseRanks.slice();p.skillPoints=Math.max(0,Number(p.skillPoints||0))+plan.refund;p.maxLevelRelearnUsed=true;
