  function useConsumableOnPokemon(itemId,pokemonId){
    const it=ITEMS[itemId],t=run?.team[pokemonId];if(!it?.consumable||!t||!t.alive||(state.items[itemId]||0)<=0)return;let did=false,msg=[];if(it.healPct&&t.hp<t.maxHp){const before=t.hp,heal=t.maxHp*it.healPct*(1+.05*skillRank("e10"));t.hp=Math.min(t.maxHp,t.hp+heal);msg.push(`+${Math.ceil(t.hp-before)} PS`);did=true;}if(it.curesStatus&&(t.status?.type||(t.confusionTurns||0)>0)){clearBattleStatus(t);msg.push("estado curado");did=true;}if(!did){toast("Ese Pokémon no necesita ese objeto");return;}state.items[itemId]=Math.max(0,(state.items[itemId]||0)-1);if(state.items[itemId]<=0)delete state.items[itemId];addLog(`${it.icon} ${it.name}: ${ownedStage(pokemonId).name} · ${msg.join(" · ")}.`);toast(`${it.name} → ${msg.join(" · ")}`);if(run?.paused&&run.pauseHpBaseline)run.pauseHpBaseline=pkPauseHpSnapshot();save();renderTeamWorld();renderFormation();renderCards();renderInventory();renderPotionInventory();
  }

  let tmInventoryTypeFilter="all";
  function renderTMInventory(){
    mtGachaRetireTicketsIfComplete(true);const g=ensureMTGachaState(),owned=Object.entries(state.tms||{}).filter(([id,v])=>v&&TMS[id]).sort((a,b)=>TMS[a[0]].number-TMS[b[0]].number);const gachaOwned=mtGachaOwnedCount(),gachaComplete=mtGachaPoolCompleted();
    const tmTypeOrder=["normal","fighting","flying","poison","ground","rock","bug","ghost","fire","water","grass","electric","psychic","ice","dragon","fairy","steel","dark"];
    const ownedTypes=[...new Set(owned.map(([id])=>TMS[id]?.move?.type).filter(Boolean))].sort((a,b)=>{const ai=tmTypeOrder.indexOf(a),bi=tmTypeOrder.indexOf(b);return (ai<0?999:ai)-(bi<0?999:bi)||(TYPE_NAMES[a]||a).localeCompare(TYPE_NAMES[b]||b,"es");});
    if(tmInventoryTypeFilter!=="all"&&!ownedTypes.includes(tmInventoryTypeFilter))tmInventoryTypeFilter="all";
    const filteredOwned=tmInventoryTypeFilter==="all"?owned:owned.filter(([id])=>TMS[id]?.move?.type===tmInventoryTypeFilter);
    if($("lootTabTmCount"))$("lootTabTmCount").textContent=`${owned.length}/50`;
    if($("lootTmTicketBadge"))$("lootTmTicketBadge").textContent=gachaComplete?`✓ Pool MT completado`:`🎟️ ${g.tickets} Ticket${g.tickets===1?"":"s"}`;
    if(lootActiveTab==="tms"&&$("lootCapacityText"))$("lootCapacityText").textContent=gachaComplete?`${owned.length}/50 MT · Pool MT 42/42 completado`:`${owned.length}/50 MT · 🎟️ ${g.tickets} Ticket${g.tickets===1?"":"s"}`;
    const gachaCard=`<div class="tm-mini-card mt-gacha-inventory-card"><div class="mt-inventory-gacha-title"><div class="mt-inventory-gacha-main">${tmCaseSpriteHTML("tm-gacha-card-sprite")}<div><b>Gachapón de MT</b><small>42 MT en el pool · cada una tiene su propia probabilidad.</small></div></div><strong>${gachaComplete?"✓ 42/42":`🎟️ ${g.tickets}`}</strong></div><small>${gachaComplete?"Pool del Gachapón completado. Los Tickets MT se retiran automáticamente y ya no vuelven a generarse.":"Completa una ruta entera desde 0 m para ganar 1 Ticket. Los checkpoints no cuentan · Infinita: 1 Ticket cada 30 km."}</small><div class="mt-gacha-inventory-actions"><button class="btn primary" type="button" data-open-mt-gacha ${gachaComplete?"disabled":""}>${gachaComplete?"Pool completado":"🎟️ Abrir Gachapón MT"}</button><span class="mt-gacha-chip">Pool ${gachaOwned}/${MT_GACHA_IDS.length}</span><span class="mt-gacha-chip">${gachaComplete?"Completado":`Pity ${Math.min(10,g.duplicateStreak)}/10`}</span></div></div>`;
    const collectionHeader=`<div class="tm-collection-header"><div class="tm-collection-emblem" aria-hidden="true">${tmCaseSpriteHTML("tm-collection-case-sprite")}</div><div class="tm-collection-intro"><span class="tm-collection-kicker">Colección de MT</span><div class="tm-collection-title-row"><h3>MT de Generación III</h3><strong>${owned.length}<small>/50</small></strong></div><div class="tm-collection-progress" aria-label="${owned.length} de 50 MT obtenidas"><span style="width:${Math.max(0,Math.min(100,owned.length/50*100)).toFixed(1)}%"></span></div><p>${owned.length?"Cada MT usa el disco oficial de su tipo. Pulsa una para ver tus Pokémon compatibles y enseñársela directamente.":"Aún no tienes MT. Completa la colección con las 42 MT del Gachapón de MT y las 8 MT únicas de los Líderes de Gimnasio."}</p><p style="margin-top:6px;font-size:8px;color:#9fb0c1">Capacidad por rareza: Común/Poco común 1 MT · Raro 2 · Épico 3 · Legendario 4. Los épicos eligen libremente 3 de sus 4 ranuras; los support usan la ranura Support.</p></div></div>`;
    const typeFilter=owned.length?`<div class="tm-type-filter-row"><label for="tmTypeFilterVisual">Filtrar por tipo</label><select class="tm-type-filter-select" data-tm-type-filter aria-label="Filtrar MT por tipo"><option value="all">Todos los tipos</option>${ownedTypes.map(type=>`<option value="${type}" ${tmInventoryTypeFilter===type?"selected":""}>${TYPE_NAMES[type]||type} · ${owned.filter(([id])=>TMS[id]?.move?.type===type).length}</option>`).join("")}</select><div class="tm-type-filter-count"><b>${filteredOwned.length}</b> de ${owned.length} obtenidas${tmInventoryTypeFilter!=="all"?` · ${TYPE_NAMES[tmInventoryTypeFilter]||tmInventoryTypeFilter}`:""}</div></div>`:"";
    const collection=collectionHeader+typeFilter+(!owned.length
      ?`<div class="tm-collection-empty-state"><b>Tu colección está vacía</b><small>Consigue tu primera MT para que aparezca aquí.</small></div>`
      :!filteredOwned.length?`<div class="tm-type-filter-empty">No tienes MT de este tipo todavía.</div>`
      :filteredOwned.map(([id])=>{
        const tm=TMS[id],m=tm.move,detail=m.kind==="support"?`${displayType(m.type)} · Estado/Apoyo`:`${displayType(m.type)} · Potencia ${m.basePower} · Precisión ${Math.round((m.tmAccuracy??1)*100)}%`;
        const compatibleOwned=(window.PokeSendaRegionBoot?.isHoennClone||GEN1_TM_COMPAT_READY)?state.owned.filter(pid=>tmIsCompatible(id,pid)).length:null;
        return `<button class="tm-mini-card tm-owned-card" type="button" data-open-tm-detail="${id}"><div class="tm-owned-card-layout">${tmSpriteHTML(id,"tm-owned-sprite")}<div class="tm-owned-card-copy"><div class="tm-owned-card-head"><b>${tm.name}</b><span>Ver compatibles ›</span></div><small>${detail} · ${compatibleOwned==null?"Compatibilidad R/B verificándose…":`${compatibleOwned} Pokémon tuyo${compatibleOwned===1?"":"s"} compatible${compatibleOwned===1?"":"s"}.`}</small><small class="tm-owned-desc">${tm.desc}</small></div></div></button>`;
      }).join(""));
    const html=gachaCard+collection;
    const wrapLoot=$("tmInventoryLoot");if(wrapLoot)wrapLoot.innerHTML=html;
    const wrapInfo=$("tmInventory");if(wrapInfo)wrapInfo.innerHTML=html;
    document.querySelectorAll("[data-open-mt-gacha]").forEach(b=>b.onclick=openMTGachaOverlay);
    document.querySelectorAll("[data-open-tm-detail]").forEach(b=>b.onclick=()=>openTMEquipOverlay(b.dataset.openTmDetail));
    document.querySelectorAll("[data-tm-type-filter]").forEach(sel=>{sel.value=tmInventoryTypeFilter;sel.onchange=()=>{tmInventoryTypeFilter=sel.value||"all";renderTMInventory();};});
  }


  function renderDamagePanel(){if(pkBackgroundCatchingUp)return;
    const wrap=$("damagePanel");if(!wrap)return;
    if(!wrap.dataset.damageTabsWired){
      wrap.dataset.damageTabsWired="1";
      wrap.addEventListener("pointerdown",e=>{const btn=e.target.closest?.("[data-damage-tab]");if(!btn||!wrap.contains(btn))return;e.preventDefault();damagePanelMode=btn.dataset.damageTab||"damage";renderDamagePanel();});
      wrap.addEventListener("keydown",e=>{const btn=e.target.closest?.("[data-damage-tab]");if(!btn||!wrap.contains(btn)||!(e.key==="Enter"||e.key===" "))return;e.preventDefault();damagePanelMode=btn.dataset.damageTab||"damage";renderDamagePanel();});
    }
    const metric=(damagePanelMode==="taken"||damagePanelMode==="healing")?damagePanelMode:"damage";
    const statSource=run?.stats||lastRunStats||{};
    const damageSource=run?.damageDone||lastDamageReport||{};
    const ids=Array.from(new Set([...Object.keys(damageSource||{}),...Object.keys(statSource||{})])).filter(id=>state.progress[id]);
    if(!ids.length){wrap.innerHTML=`<div class="damage-tabs"><button class="damage-tab ${metric==="damage"?"active":""}" type="button" data-damage-tab="damage">Daño acumulado</button><button class="damage-tab ${metric==="taken"?"active":""}" type="button" data-damage-tab="taken">Daño recibido</button><button class="damage-tab ${metric==="healing"?"active":""}" type="button" data-damage-tab="healing">Curación</button></div><div class="damage-empty">La información de combate aparecerá cuando inicies una expedición.</div>`;return;}
    const cfg=metric==="healing"
      ? {title:'💚 Curación',empty:'Todavía no hay curación registrada en esta expedición.',small:'curación total',fillA:'#56c57b',fillB:'#a8efb0'}
      : metric==="taken"
        ? {title:'🛡 Daño recibido',empty:'Todavía no hay daño recibido registrado en esta expedición.',small:'daño recibido',fillA:'#5a8ef0',fillB:'#88baff'}
        : {title:'⚔ Daño acumulado',empty:'Todavía no hay daño acumulado registrado en esta expedición.',small:'daño total',fillA:'#d86455',fillB:'#ef9c55'};
    const valueFor=id=>metric==="healing"?Number(statSource[id]?.healing||0):metric==="taken"?Number(statSource[id]?.damageTaken||0):Number(damageSource[id]??statSource[id]?.damage??0);
    const entries=ids.map(id=>({id,val:valueFor(id)}));
    const total=entries.reduce((s,e)=>s+e.val,0);
    const max=Math.max(1,...entries.map(e=>e.val));
    entries.sort((a,b)=>b.val-a.val||ownedStage(a.id).name.localeCompare(ownedStage(b.id).name,'es'));
    wrap.innerHTML=`<div class="damage-tabs"><button class="damage-tab ${metric==='damage'?'active':''}" type="button" data-damage-tab="damage">Daño acumulado</button><button class="damage-tab ${metric==='taken'?'active':''}" type="button" data-damage-tab="taken">Daño recibido</button><button class="damage-tab ${metric==='healing'?'active':''}" type="button" data-damage-tab="healing">Curación</button></div>${total<=0?`<div class="damage-head"><b>${cfg.title}</b><div class="grow"></div><small>0 total</small></div><div class="damage-empty">${cfg.empty}</div>`:`<div class="damage-head"><b>${cfg.title}</b><div class="grow"></div><small>${Math.round(total).toLocaleString('es-CL')} total</small></div><div class="damage-list">${entries.map(({id,val})=>{const st=ownedStage(id),pct=total?val/total*100:0,bar=max?val/max*100:0;return `<div class="damage-row"><img src="${spriteUrl(st.dex)}" alt="${st.name}"><div class="damage-main"><b>${st.name}</b><div class="damage-bar"><div class="damage-fill" style="width:${bar.toFixed(1)}%;--fill-a:${cfg.fillA};--fill-b:${cfg.fillB}"></div></div></div><div class="damage-number"><b>${Math.round(val).toLocaleString('es-CL')}</b><small>${pct.toFixed(1)}%</small></div></div>`;}).join('')}</div><div class="damage-note">${cfg.small}</div>`}`;
  }

