  function encounterPool(){
    const route=ROUTES[state.currentRoute];
    if(state.currentRoute==="route1"&&run.distance<1000)return window.PokeSendaRegionBoot?.isHoennClone?["wurmple","cascoon","taillow","slakoth","nincada","skitty","volbeat"]:["rattata","caterpie","weedle","pidgey","spearow","paras","venonat"];
    return route.enemies;
  }

  function spawnRound(){
    if(!run||run.failed||run.completed||run.rewardPending||run.paused)return;
    if(run.pendingBoss){spawnBoss();return;}
    run.roundIndex++;run.roundXp=0;run.roundCombatants=[];markRoundCombatants(battleIds());
    const pool=encounterPool(),routeIdx=isInfiniteMode()?3:Math.max(0,ROUTE_ORDER.indexOf(state.currentRoute)),km=Math.floor(run.distance/1000);
    const count=Math.min(4,Math.max(2,battleIds().length+1+(routeIdx>0||km>=5?1:0))),keys=[];
    const level=enemyLevelForDistance(run.distance),mainId=pool[Math.floor(Math.random()*pool.length)],mainTypes=stageFor(mainId,level).types;
    const sameType=pool.filter(id=>id!==mainId&&stageFor(id,level).types.some(t=>mainTypes.includes(t)));
    const alt=(count>1&&sameType.length&&Math.random()<.38)?sameType[Math.floor(Math.random()*sameType.length)]:null;
    for(let i=0;i<count;i++)keys.push(mainId);
    if(alt){const idx=Math.floor(Math.random()*count);keys[idx]=alt;}
    // La oleada se siente como una manada: todos iguales o, como máximo, un intruso que comparte tipo.
    for(let i=keys.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[keys[i],keys[j]]=[keys[j],keys[i]];}
    const levelOffsets=[-2,-1,0,0,1,2];
    run.enemies=keys.map((id,i)=>{const variance=levelOffsets[Math.floor(Math.random()*levelOffsets.length)],lv=Math.max(1,Math.min(MAX_LEVEL,level+variance));return makeEnemy(id,i,false,lv);});
    const levels=run.enemies.map(e=>e.level),minLv=Math.min(...levels),maxLv=Math.max(...levels),lvText=minLv===maxLv?`Nv.${minLv}`:`Nv.${minLv}–${maxLv}`;
    addLog(`Manada ${lvText} · ${count} rivales: ${run.enemies.map(e=>`${e.name} Nv.${e.level}`).join(" · ")}.`);
    renderEnemyTeam();
  }

  function spawnBoss(){
    run.roundIndex++;run.roundXp=0;run.roundCombatants=[];markRoundCombatants(battleIds());
    const rawKm=Math.max(1,Math.round(run.distance/1000)),route=ROUTES[state.currentRoute];let bossId,forcedLevel;
    if(isInfiniteMode()){
      const legends=window.PokeSendaRegionBoot?.isHoennClone?["regirock","regice","registeel","latias","latios","kyogre","groudon","rayquaza","jirachi","deoxys"]:["moltres","zapdos","articuno","mewtwo","mew"],tier=Math.max(1,Math.round(rawKm/10));
      if(rawKm%10===0)bossId=legends[(tier-1)%legends.length];else bossId=route.bosses[(rawKm-1)%route.bosses.length];forcedLevel=MAX_LEVEL;
    }else{const km=Math.max(1,Math.min(10,rawKm));bossId=route.bosses[km-1];forcedLevel=km===10?(route.finalBossLevel||25):null;}
    run.enemies=[makeEnemy(bossId,0,true,forcedLevel)];run.pendingBoss=false;run.bossActive=true;
    addLog(`⚠ JEFE ${rawKm} km: ${run.enemies[0].name}${isInfiniteMode()&&rawKm%10===0?" · GUARDIÁN DE HITO":""}.`);flash(isInfiniteMode()&&rawKm%10===0?`¡Guardia del hito ${rawKm/10}!`:`¡Jefe del km ${rawKm}!`);renderEnemyTeam();
  }

