  $("bgMusic")?.addEventListener("play",()=>{if(introMusicStage==="intro"){try{$("bgMusic").pause();}catch(_){ }ensureIntroPlaying();}else{stopIntroMusic(false);silenceMusicSourcePlayers();}});
  $("bgMusic")?.addEventListener("ended",()=>{if(introMusicStage!=="intro")advanceMusicPlaylist();});
