  let mtGachaRolling=false,mtGachaSpinTimer=null;
  function ensureMTGachaState(){state.mtGacha=state.mtGacha&&typeof state.mtGacha==="object"?state.mtGacha:{};state.mtGacha.tickets=Math.max(0,Math.floor(Number(state.mtGacha.tickets||0)));state.mtGacha.pulls=Math.max(0,Math.floor(Number(state.mtGacha.pulls||0)));state.mtGacha.duplicateStreak=Math.max(0,Math.floor(Number(state.mtGacha.duplicateStreak||0)));state.mtGacha.history=Array.isArray(state.mtGacha.history)?state.mtGacha.history.slice(0,30):[];return state.mtGacha;}
