  function unlockedMoves(id,kind){const p=state.progress[id],moves=movesFor(id);return moves.map((m,i)=>({m,i,rank:p.moveRanks?.[i]||0})).filter(x=>x.m.kind===kind&&(p.stageIndex||0)>=(x.m.unlockStage||0)&&(x.rank>0||x.m.kind==="support"));}
