    const beforeEnemies=new Map(livingEnemies().map(e=>[e.uid,e.hp])),beforeSelf=t?.hp||0;
    tmBasePokemonAttackMove(id,enemy,move,rank);
    if(!run||!t?.alive)return;let dealt=0;for(const e of run.enemies||[]){const b=beforeEnemies.get(e.uid);if(b!=null)dealt+=Math.max(0,b-Math.max(0,e.hp));}
