  function nextUnvisitedCenter(old,target){
    if(!run)return null;return POKEMON_CENTERS.find(c=>c>old&&c<=target&&!(run.centersVisited||[]).includes(c))||null;
  }
  function healAtCenter(meters){
    if(!run)return;for(const [id,t] of Object.entries(run.team)){const d=derived(id);const pkPrevHp=t.hp;t.maxHp=d.maxHp;t.hp=d.maxHp;t.alive=true;t.attackTimer=.35;t.tempReduction=0;t.powerBuff=0;t.haste=0;t.autoPotionCooldown=0;clearBattleStatus(t);pkFxHealAlly(id,Math.max(0,d.maxHp-pkPrevHp));}
    const rs=routeState();rs.centersSeen=Array.isArray(rs.centersSeen)?rs.centersSeen:[];
    if(!rs.centersSeen.includes(meters))rs.centersSeen.push(meters);
    if(!(run.centersVisited||[]).includes(meters))run.centersVisited.push(meters);rs.checkpoint=meters;run.checkpoint=meters;run.centerBuffRounds=20;save();renderTeamWorld();renderCards();
  }
  const CENTER_AUTO_CONTINUE_MS=10000;
  let centerContinueTimer=null,centerContinueDeadline=0;
  function stopCenterContinueTimer(){
    if(centerContinueTimer){clearInterval(centerContinueTimer);centerContinueTimer=null;}
    centerContinueDeadline=0;
  }
  function updateCenterContinueTimer(){
    if(!run?.centerPending||$("centerOverlay")?.classList.contains("hidden")){stopCenterContinueTimer();return;}
    const left=Math.max(0,centerContinueDeadline-performance.now()),ratio=Math.max(0,Math.min(1,left/CENTER_AUTO_CONTINUE_MS));
    if($("centerTimerText"))$("centerTimerText").textContent=`${(left/1000).toFixed(1)} s`;
    if($("centerTimerFill"))$("centerTimerFill").style.width=`${ratio*100}%`;
    if($("centerTimer"))$("centerTimer").classList.toggle("urgent",left<=3000);
    if(left<=0){
      const overdue=Math.max(0,(performance.now()-centerContinueDeadline)/1000);
      stopCenterContinueTimer();
      if(run?.centerPending){addLog("⏱️ Centro Pokémon: continuación automática.");closePokemonCenter(true);if(overdue>.35&&run)pkProcessBackgroundGap(overdue);}
    }
  }
  function startCenterContinueTimer(){
    stopCenterContinueTimer();centerContinueDeadline=performance.now()+CENTER_AUTO_CONTINUE_MS;
    if($("centerTimer"))$("centerTimer").classList.remove("urgent");
    if($("centerTimerFill"))$("centerTimerFill").style.width="100%";
    if($("centerTimerText"))$("centerTimerText").textContent="10.0 s";
    centerContinueTimer=setInterval(updateCenterContinueTimer,100);updateCenterContinueTimer();
  }
  function openPokemonCenter(meters){
    if(!run)return;
    const rs=routeState();rs.centersSeen=Array.isArray(rs.centersSeen)?rs.centersSeen:[];
    const firstVisit=!rs.centersSeen.includes(meters);
    stopLoop();run.paused=true;run.centerPending=firstVisit;run.centerPauseWallMs=firstVisit?Date.now():0;healAtCenter(meters);
    if(!firstVisit){
      stopCenterContinueTimer();$("centerOverlay").classList.add("hidden");run.centerPending=false;run.paused=false;run.spawnDelay=.35;run.lastTick=performance.now();run.wallTickMs=Date.now();
      addLog(`🏥 Centro Pokémon ${formatMeters(meters)}: equipo restaurado automáticamente, sin detener el farmeo.`);renderEverything();if(!pkFloatingDriver&&!pkBackgroundCatchingUp)loop=setInterval(tick,100);return;
    }
    $("centerText").textContent=`Llegaste por primera vez al Centro Pokémon de ${formatMeters(meters)}. Zona de descanso: todo tu equipo fue curado y revivido. Checkpoint de seguridad guardado en ${formatMeters(meters)}.`;$("centerOverlay").classList.remove("hidden");addLog(`🏥 Nuevo Centro Pokémon ${formatMeters(meters)}: equipo restaurado. Tu punto de farmeo sigue en ${formatMeters(run.farmStart||0)}.`);renderEverything();startCenterContinueTimer();
  }
  function closePokemonCenter(auto=false){
    stopCenterContinueTimer();if(!run)return;$("centerOverlay").classList.add("hidden");run.centerPending=false;run.centerPauseWallMs=0;run.paused=false;run.spawnDelay=.7;run.lastTick=performance.now();run.wallTickMs=Date.now();stopLoop();if(!pkFloatingDriver&&!pkBackgroundCatchingUp)loop=setInterval(tick,100);renderEverything();
  }
