  // V31.11 · El Gachapon de 8 h usa una tabla premium independiente del Gachapon normal.
  // No aparecen Pokémon comunes y la probabilidad total se reparte por rareza,
  // evitando que una categoría domine solo por tener más especies disponibles.
  const TIMED_GACHA_RARITY_CHANCE={common:0,uncommon:.22,rare:.48,epic:.28,legendary:.02};
  function timedGachaPool(){
    const map=new Map(),routes=(state.unlockedRoutes||["route1"]).filter(id=>ROUTES[id]);
    for(const routeId of routes){
      for(const x of rewardPoolFor(routeId,10)){
        if(x.rarity==="common")continue;
        const old=map.get(x.id);
        if(old){
          if(ROUTE_ORDER.indexOf(routeId)>ROUTE_ORDER.indexOf(old.sourceRoute))old.sourceRoute=routeId;
        }else map.set(x.id,{...x,sourceRoute:routeId});
      }
    }
    const pool=[...map.values()],groups={};
    for(const x of pool)(groups[x.rarity]||(groups[x.rarity]=[])).push(x);
    for(const [rarity,items] of Object.entries(groups)){
      const rarityChance=TIMED_GACHA_RARITY_CHANCE[rarity]||0;
      const perPokemon=items.length?rarityChance/items.length:0;
      for(const x of items)x.weight=perPokemon;
    }
    return pool.filter(x=>x.weight>0);
  }
