    let level=1;
    if(reward?.infiniteGacha)level=Number(infiniteCaptureInfo(entry.id,reward.infiniteMilestone,entry.rarity)?.level||1);
    else{
      const sourceRoute=reward?.timedGacha?(reward.routeId||state.currentRoute):(reward?.routeId||state.currentRoute);
      level=captureLevelFor(sourceRoute,reward?.km||10,entry.rarity);
    }
