  let activeHelpTab="start";
  const normalizeHelpSearch=text=>String(text||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim();
  function helpTabLabel(tab){const b=$("infoPanel")?.querySelector(`[data-help-tab="${tab}"]`);return b?.textContent?.trim()||tab;}
  function helpNextRecommendation(){
    const team=activeIds(),dex=pokedexDiscoveredCount(),badges=achievementGymBadgeCount();
    if(!state.starter)return {goal:"Elige tu primer compañero",why:"Ese es el único paso obligatorio antes de comenzar.",tab:"pokemon"};
    if(team.length<3)return {goal:"Completa tus 3 puestos de combate",why:`Ahora tienes ${team.length}/3. Guardia + Asalto + Apoyo te dan una base mucho más estable.`,tab:"pokemon"};
    if(run)return {goal:"Deja avanzar la expedición y observa dónde te cuesta",why:"Si el equipo cae, usa el resumen final para detectar quién recibe demasiado daño o aporta poco.",tab:"combat"};
    if(Number(state.routes?.route1?.completions||0)<1)return {goal:`Completa ${window.PokeSendaRegionBoot?.isHoennClone?"Archipiélago Celeste":"Ruta Verde"}`,why:"Tu siguiente gran desbloqueo está al final del primer acto.",tab:"route"};
    if(Number(state.routes?.route2?.completions||0)<1)return {goal:`Avanza por ${window.PokeSendaRegionBoot?.isHoennClone?"Caldera Magma":"Cueva Rocosa"}`,why:"Aquí empieza a importar más la combinación de tipos, objetos y posiciones.",tab:"route"};
    if(Number(state.routes?.route3?.completions||0)<1)return {goal:`Completa ${window.PokeSendaRegionBoot?.isHoennClone?"Senda Esmeralda":"Costa Azul"}`,why:"Terminar el tercer acto abre el endgame principal.",tab:"route"};
    if(badges<8)return {goal:`Consigue las Medallas restantes (${badges}/8)`,why:"Los Gimnasios son el siguiente desafío natural después de las rutas.",tab:"gyms"};
    const dexGoal=pokedexTotalCount();
    if(dex<dexGoal)return {goal:`Completa la Pokédex (${dex}/${dexGoal})`,why:`Al registrar las ${dexGoal} especies/formas regionales recibirás la recompensa de Pokédex completa.`,tab:"achievements"};
    if(shinyDexCount()<dexGoal)return {goal:`Empieza la Pokédex Shiny (${shinyDexCount()}/${dexGoal})`,why:"Usa tus Tickets Shiny especiales y luego continúa la caza con Gachapones e Infinita.",tab:"capture"};
    return {goal:"Optimiza tu récord y completa los desafíos de perfección",why:"Ya terminaste la colección principal; ahora manda la eficiencia del equipo, estrellas, niveles y récord de Infinita.",tab:"ux"};
  }
  function renderHelpOverview(){
    const route=ROUTES[state.currentRoute]||ROUTES.route1,rs=routeState(),team=activeIds();
    const set=(id,text)=>{const el=$(id);if(el)el.textContent=text;};
    set("helpNowRoute",route.name+(isInfiniteMode()?" · récord "+formatMeters(state.infiniteExpedition?.bestDistance||0):""));
    set("helpNowTeam",`${team.length}/6 · ${Math.min(3,team.length)} combate · ${Math.max(0,team.length-3)} banca`);
    set("helpNowCheckpoint",isInfiniteMode()?"0 m fijo":formatMeters(routeStartPoint(rs)));
    set("helpNowMoney",`₽${Math.floor(state.pokedollars||0).toLocaleString("es-CL")}`);
    set("helpNowDex",`${pokedexDiscoveredCount()}/${pokedexTotalCount()}`);
    set("helpNowEvents",isInfiniteMode()?"No disponibles":state.options.routeEvents===false?"Desactivados":"Activados");
    const next=helpNextRecommendation();set("helpNextGoal",next.goal);set("helpNextWhy",next.why);const btn=$("helpNextActionBtn");if(btn){btn.dataset.helpGo=next.tab;btn.textContent=`Ver ${helpTabLabel(next.tab)}`;}
  }
  function setHelpTab(tab,{scroll=true,clearSearch=false}={}){
    const panel=$("infoPanel");if(!panel)return;const valid=[...panel.querySelectorAll("[data-help-page]")].some(x=>x.dataset.helpPage===tab);if(!valid)tab="start";activeHelpTab=tab;
    panel.querySelectorAll("[data-help-page]").forEach(page=>page.classList.toggle("hidden",page.dataset.helpPage!==tab));
    panel.querySelectorAll("[data-help-tab]").forEach(btn=>btn.classList.toggle("active",btn.dataset.helpTab===tab));
    renderHelpOverview();if(tab==="route")renderRouteInfo();
    if(clearSearch){const input=$("helpSearch");if(input)input.value="";renderHelpSearch("");}
    if(scroll)panel.scrollTo({top:0,behavior:state.options.animations?"smooth":"auto"});
  }
  function helpSnippet(text,query){
    const clean=String(text||"").replace(/\s+/g," ").trim(),nq=normalizeHelpSearch(query),normalized=normalizeHelpSearch(clean),idx=normalized.indexOf(nq);if(idx<0)return clean.slice(0,170)+(clean.length>170?"…":"");
    const start=Math.max(0,idx-65),end=Math.min(clean.length,idx+Math.max(30,query.length)+105);return (start?"…":"")+clean.slice(start,end)+(end<clean.length?"…":"");
  }
  function renderHelpSearch(query){
    const panel=$("infoPanel"),box=$("helpSearchResults");if(!panel||!box)return;const q=normalizeHelpSearch(query);
    box.innerHTML="";if(q.length<2){box.classList.add("hidden");return;}
    const matches=[];panel.querySelectorAll("[data-help-page]").forEach(page=>{const text=page.textContent||"";if(normalizeHelpSearch(text).includes(q))matches.push({tab:page.dataset.helpPage,title:page.dataset.helpTitle||helpTabLabel(page.dataset.helpPage),text});});
    box.classList.remove("hidden");const summary=document.createElement("div");summary.className="help-search-summary";summary.textContent=matches.length?`${matches.length} sección${matches.length===1?"":"es"} con resultados. Pulsa una para abrirla.`:`No encontré “${query}”. Prueba una palabra más simple: Gachapon, Casino, XP, tipo, objeto, MT, Shiny, banca, checkpoint, Gimnasio o ticket.`;box.appendChild(summary);
    matches.slice(0,10).forEach(m=>{const btn=document.createElement("button");btn.type="button";btn.className="help-search-hit";btn.dataset.helpJump=m.tab;const title=document.createElement("b");title.textContent=m.title;const snippet=document.createElement("small");snippet.textContent=helpSnippet(m.text,query);btn.append(title,snippet);btn.addEventListener("click",()=>{const input=$("helpSearch");if(input)input.value="";renderHelpSearch("");setHelpTab(m.tab,{scroll:true});});box.appendChild(btn);});
  }
