  function uxCompatibleInventoryItem(id){return Object.entries(state.items||{}).some(([itemId,n])=>n>0&&ITEMS[itemId]&&!ITEMS[itemId].consumable&&!ITEMS[itemId].evolutionStone&&isItemCompatible(itemId,id));}
