  // ----- Centro contextual -----
  function uxCurrentSurface(){if($("summary")?.classList.contains("show"))return"Resumen de expedición";if(!$("lootPanel")?.classList.contains("hidden"))return"Inventario / Loot";if(!$("pokedexOverlay")?.classList.contains("hidden"))return"Pokédex";if(!$("pcBoxOverlay")?.classList.contains("hidden"))return"Caja PC";if(!$("achievementsOverlay")?.classList.contains("hidden"))return"Logros";if(!$("skillTreeOverlay")?.classList.contains("hidden"))return"Árbol del Entrenador";if(run?.paused)return"Expedición en pausa";if(run)return"Expedición en curso";return"Preparación de expedición";}
  function uxNextRecommendation(){
    const ux=uxEnsureState(),unseen=(state.unlockedRoutes||[]).filter(id=>!ux.seenRoutes.includes(id));if(infiniteUnlocked()&&!ux.seenRoutes.includes(INFINITE_ROUTE_ID))unseen.push(INFINITE_ROUTE_ID);
    if(run){const alive=battleIds().filter(id=>run.team[id]?.alive),low=alive.map(id=>({id,r:run.team[id].hp/run.team[id].maxHp})).sort((a,b)=>a.r-b.r)[0];if(low&&low.r<=.22)return{title:"Un activo está muy herido",text:`${ownedStage(low.id).name} está al ${(low.r*100).toFixed(0)}% de PS. Pausa si quieres revisar objeto/posición o abre el Botiquín.`,actions:["loot","why"]};const next=isInfiniteMode()?(Math.floor((run.distance||0)/1000)+1)*1000:Math.min(MAX_DISTANCE,(Math.floor((run.distance||0)/1000)+1)*1000);return{title:run.paused?"Aprovecha la pausa":"Sigue hasta el próximo jefe",text:run.paused?"Puedes reordenar los integrantes que iniciaron, cambiar objetos y revisar fichas. Para sustituir un integrante debes Parar.":`Próximo jefe a ${formatMeters(next)}. El combate avanza solo; vigila PS, estados y el daño del equipo.`,actions:["why","guide"]};}
    if(unseen.length){const id=unseen[0],name=id===INFINITE_ROUTE_ID?"Expedición Infinita":ROUTES[id]?.name||"nueva ruta";return{title:`Tienes contenido nuevo: ${name}`,text:"La ruta acaba de quedar disponible. Selecciónala cuando quieras para marcarla como revisada.",actions:["why","guide"]};}
    const improved=uxOwnedPokemonWithImprovements();if(improved.length)return{title:`${improved.length} Pokémon con mejoras disponibles`,text:"Hay puntos de movimiento, estrellas, evoluciones, objetos o MT que ya puedes aprovechar. La Caja y la Formación muestran indicadores verdes.",actions:["box","guide"]};
    const affordable=uxAffordableSkillIds();if(affordable.length)return{title:`Puedes comprar ${affordable.length} mejora${affordable.length===1?"":"s"} del Árbol`,text:"Tienes Pokédólares suficientes para uno o más nodos desbloqueados. Revisa coste y efecto en el nodo y compra directamente con un clic.",actions:["tree","why"]};
    const newCount=(state.dexUnread||[]).length+(state.itemUnread||[]).length+(state.achievements?.unread||[]).length;if(newCount)return{title:`${newCount} novedad${newCount===1?"":"es"} por revisar`,text:"Los avisos rojos NUEVO te dicen exactamente dónde hay contenido que todavía no abriste.",actions:["pokedex","loot"]};
    return{title:"Tu equipo está listo",text:`Puedes iniciar desde ${isInfiniteMode()?"0 m":formatMeters(routeStartPoint())}. Si te atascas, el resumen inteligente del próximo intento te ayudará a decidir qué ajustar.`,actions:["guide","why"]};
  }
  function uxContextReasonRows(){const rows=[];if(run)rows.push(["🔒","Equipo bloqueado","Es intencional: la run conserva los mismos participantes. Pausa permite reordenar; Parar permite sustituir."]);if(isInfiniteMode())rows.push(["♾","Automatización limitada","Auto-repetir y Auto Poké Ball están bloqueados: la Infinita conserva el resumen y sus Gachapones se abren manualmente."]);if(skillRank("a5")<1)rows.push(["💉","Auto-Poción bloqueada","Se desbloquea con Protocolo de Emergencia en el Árbol."]);const loot=(state.itemUnread||[]).length,dex=(state.dexUnread||[]).length;if(loot||dex)rows.push(["🆕","Tienes contenido NUEVO",`${loot?`${loot} objeto${loot===1?"":"s"}`:""}${loot&&dex?" · ":""}${dex?`${dex} entrada${dex===1?"":"s"} de Pokédex`:""} sin revisar.`]);return rows.slice(0,4).map(([i,t,s])=>`<div class="ux-reason-row"><div class="ux-reason-icon">${i}</div><div><b>${uxHtml(t)}</b><small>${uxHtml(s)}</small></div></div>`).join("")||'<div class="ux-reason-row"><div class="ux-reason-icon">✓</div><div><b>Sin bloqueos importantes</b><small>Tu estado actual no necesita una explicación especial.</small></div></div>';}
  function uxRenderContext(){
    const body=$("uxContextBody");if(!body)return;const route=ROUTES[state.currentRoute]?.name||"Ruta",team=activeIds(),rec=uxNextRecommendation(),newCount=(state.dexUnread||[]).length+(state.itemUnread||[]).length+(state.achievements?.unread||[]).length,improve=uxOwnedPokemonWithImprovements().length,actionLabel={guide:"❔ Guía",why:"❓ ¿Por qué?",loot:"🎒 Loot",tree:"🌳 Árbol",box:"💻 Caja",pokedex:"📘 Pokédex"};
    body.innerHTML=`<div class="ux-context-status"><div class="ux-context-metric"><span>Ahora</span><b>${uxHtml(uxCurrentSurface())}</b></div><div class="ux-context-metric"><span>Ruta</span><b>${uxHtml(route)}</b></div><div class="ux-context-metric"><span>Equipo</span><b>${team.length}/6 · ${Math.min(3,team.length)} activos</b></div><div class="ux-context-metric"><span>Salida</span><b>${isInfiniteMode()?"0 m":formatMeters(routeStartPoint())}</b></div><div class="ux-context-metric"><span>NUEVO</span><b>${newCount} pendiente${newCount===1?"":"s"}</b></div><div class="ux-context-metric"><span>MEJORA</span><b>${improve} Pokémon</b></div></div><div class="ux-next-card"><div class="ux-next-kicker">SIGUIENTE PASO RECOMENDADO</div><h3>${uxHtml(rec.title)}</h3><p>${uxHtml(rec.text)}</p><div class="ux-context-actions">${[...new Set(rec.actions)].map(a=>`<button class="btn" type="button" data-ux-action="${a}">${actionLabel[a]||a}</button>`).join("")}${rec.actions.includes("why")?"":'<button class="btn" type="button" data-ux-action="why">❓ Explicar bloqueos</button>'}</div></div><div class="ux-context-section"><div class="ux-context-section-title">Por qué ves esto ahora</div>${uxContextReasonRows()}</div><div class="ux-context-section"><div class="ux-context-section-title">Accesos rápidos</div><div class="ux-context-actions"><button class="btn" data-ux-action="guide">❔ Guía completa</button><button class="btn" data-ux-action="why">❓ ¿Por qué?</button><button class="btn" data-ux-action="loot">🎒 Loot</button><button class="btn" data-ux-action="tree">🌳 Árbol</button><button class="btn" data-ux-action="box">💻 Caja</button></div></div>`;
    body.querySelectorAll("[data-ux-action]").forEach(btn=>btn.addEventListener("click",()=>uxContextAction(btn.dataset.uxAction)));
  }
