  const PK_SHIRTS=["#e3350d","#2a6bd4","#2fa45a","#f2b31c","#7a3fd1","#e0559a","#22262e"];
  const PK_HAIRS=["#5b3a1e","#22262e","#e0b13c","#d4552f","#a33ea1"];

  function pkTrainerOpts(){
    const t=state.trainerAvatar;
    return t&&typeof t==="object"?t:{name:"",gender:"m",hat:true,shirt:PK_SHIRTS[0],hair:PK_HAIRS[0]};
  }
  function pkTrainerSVG(o,back,px){
    try{
      let rows=(back?(o.gender==="f"?PK_BACK_F:PK_BACK_M):(o.gender==="f"?PK_FRONT_F:PK_FRONT_M)).slice();
      if(o.hat){rows[1]="....CCCCCCCC....";rows[2]=back?"..CCCCCCCCCCCC..":"..WWCCCCCCCCWW..";}
      const pal={...PK_PAL_BASE,H:o.hair||PK_HAIRS[0],T:o.shirt||PK_SHIRTS[0]};
      let rects="";
      rows.forEach((row,y)=>{for(let x=0;x<row.length;x++){const c=pal[row[x]];if(c)rects+=`<rect x="${x}" y="${y}" width="1" height="1" fill="${c}"/>`;}});
      const h=rows.length;
      return `<svg viewBox="0 0 16 ${h}" width="${px}" height="${Math.round(px*h/16)}" shape-rendering="crispEdges" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${rects}</svg>`;
    }catch(e){return "";}
  }
  function pkRenderTrainers(){
    const o=pkTrainerOpts();
    const mk=$("pkTrainerMarker");if(mk)mk.innerHTML=pkTrainerSVG(o,false,22);
    const tb=$("pkTrainerBack");if(tb)tb.innerHTML=pkTrainerSVG(o,true,104);
  }

  let pkCreatorFirstTime=false,pkDraft=null;
  function pkOpenCreator(firstTime){
    pkCreatorFirstTime=!!firstTime;
    pkDraft={...pkTrainerOpts()};
    const ov=$("pkCreatorOverlay");if(!ov)return;
    if(firstTime)$("mainMenu").classList.add("hidden");
    $("pkCreatorCancel").classList.toggle("hidden",firstTime);
    $("pkCreatorOk").textContent=pkDraft.name||firstTime?"¡Comenzar aventura!":"Guardar personaje";
    $("pkNameInput").value=pkDraft.name||"";
    ov.classList.remove("hidden");
    pkRefreshCreator();
  }
  function pkCloseCreator(){ $("pkCreatorOverlay").classList.add("hidden"); }
  function pkRefreshCreator(){
    if(!pkDraft)return;
    $("pkPreview").innerHTML=pkTrainerSVG(pkDraft,false,120);
    $("pkPreviewName").textContent=(pkDraft.name||"¿Quién eres?")+(pkDraft.gender==="f"?" · Chica":" · Chico");
    $("pkGenderM").classList.toggle("active",pkDraft.gender!=="f");
    $("pkGenderF").classList.toggle("active",pkDraft.gender==="f");
    $("pkHatOn").classList.toggle("active",!!pkDraft.hat);
    $("pkHatOff").classList.toggle("active",!pkDraft.hat);
    document.querySelectorAll("#pkShirtRow .pk-swatch").forEach(b=>b.classList.toggle("active",b.dataset.color===pkDraft.shirt));
    document.querySelectorAll("#pkHairRow .pk-swatch").forEach(b=>b.classList.toggle("active",b.dataset.color===pkDraft.hair));
  }
  function pkConfirmCreator(){
    const name=($("pkNameInput").value||"").trim().slice(0,12)||"Entrenador";
    state.trainerAvatar={...pkDraft,name};
    save();pkRenderTrainers();pkCloseCreator();
    if(pkCreatorFirstTime){
      try{setTimeout(()=>window.PokeSendaPlayers?.autoJoin?.(),0);}catch(_){}
      if(!state.starter)$("starterOverlay").classList.remove("hidden");
      else{renderEverything();}
    }else{
      $("mainMenu").classList.remove("hidden");updateMenuInfo();
    }
  }
  function pkShowFirstWelcome(){
    const ov=$("pkFirstWelcomeOverlay");if(!ov)return false;
    ov.classList.remove("hidden");return true;
  }
  function pkContinueAfterFirstWelcome(){
    $("pkFirstWelcomeOverlay")?.classList.add("hidden");
    state.pokesendaWelcomeSeen=true;save();
    if(!state.starter)$("starterOverlay").classList.remove("hidden");else renderEverything();
  }
  $("pkFirstWelcomeContinueBtn")?.addEventListener("click",pkContinueAfterFirstWelcome);
  function pkOnPlay(){
    $("mainMenu").classList.add("hidden");
    startMusic();
    try{window.PokeSendaPlayers?.autoJoin?.();}catch(_){}
    if(!state.trainerAvatar){pkOpenCreator(true);return;}
    if(!state.starter&&!state.pokesendaWelcomeSeen&&pkShowFirstWelcome())return;
    if(!state.starter)$("starterOverlay").classList.remove("hidden");else renderEverything();
  }
  // V36.72.2 · Entrada regional directa: reutiliza exactamente el flujo seguro de Jugar/Continuar.
  window.PokeSendaOpenKantoCamp=()=>{try{pkOnPlay();return true;}catch(_){return false;}};

  (function pkInitTrainer(){
    try{
      // Marcador en la barra de progreso
      const rp=document.querySelector(".route-progress");
      if(rp&&!$("pkTrainerMarker")){
        const mk=document.createElement("span");mk.id="pkTrainerMarker";mk.title="Tu entrenador";
        rp.insertBefore(mk,rp.querySelector(".timebar"));
      }
      // Entrenador de espaldas en el campo
      const field=$("field");
      if(field&&!$("pkTrainerBack")){
        const tb=document.createElement("div");tb.id="pkTrainerBack";tb.className="pk-trainer-back";
        field.appendChild(tb);
      }
      // Acceso al avatar desde el menú. En una partida nueva se vuelve una elección obligatoria.
      const optBtn=$("menuOptionsBtn");
      if(optBtn&&!$("menuTrainerBtn")){
        const btn=document.createElement("button");btn.id="menuTrainerBtn";btn.className="btn";btn.type="button";
        const avatarReady=!!state.trainerAvatar;
        btn.textContent=avatarReady?"Cambiar avatar":"Elegir avatar";
        btn.title=avatarReady?"Cambiar el avatar o nombre de tu Entrenador":"Debes elegir tu avatar antes de comenzar la aventura";
        btn.classList.toggle("primary",!avatarReady);
        optBtn.parentNode.insertBefore(btn,optBtn);
        btn.addEventListener("click",()=>pkOpenCreator(!state.trainerAvatar));
      }
      // Overlay creador
      if(!$("pkCreatorOverlay")){
        const ov=document.createElement("div");ov.id="pkCreatorOverlay";ov.className="overlay hidden";
        ov.innerHTML=`<div class="modal-box pk-creator" onclick="event.stopPropagation()">
          <div class="pokemon-detail-head"><h2>👤 Crea a tu Entrenador</h2><div class="grow"></div><button id="pkCreatorCancel" class="btn hidden" type="button">Cancelar</button></div>
          <div class="tiny muted">Tu personaje aparecerá caminando en la barra de ruta y te acompañará de espaldas en cada combate, como en los juegos de Nintendo.</div>
          <div class="pk-creator-body">
            <div class="pk-creator-preview"><div id="pkPreview"></div><div id="pkPreviewName" class="pk-creator-name"></div></div>
            <div class="pk-creator-controls">
              <label class="pk-field-label" for="pkNameInput">Tu nombre de entrenador</label>
              <input id="pkNameInput" maxlength="12" placeholder="Ej: Red, Misty, Tibu..." autocomplete="off" spellcheck="false">
              <div class="pk-field-label">Personaje</div>
              <div class="pk-row"><button id="pkGenderM" class="btn pk-choice" type="button">👦 Chico · pantalón</button><button id="pkGenderF" class="btn pk-choice" type="button">👧 Chica · falda</button></div>
              <div class="pk-field-label">Gorro</div>
              <div class="pk-row"><button id="pkHatOn" class="btn pk-choice" type="button">🧢 Con gorro</button><button id="pkHatOff" class="btn pk-choice" type="button">💨 Sin gorro</button></div>
              <div class="pk-field-label">Color de polera</div>
              <div class="pk-row pk-swatches" id="pkShirtRow">${PK_SHIRTS.map(c=>`<button class="pk-swatch" type="button" data-kind="shirt" data-color="${c}" style="background:${c}" aria-label="Polera ${c}"></button>`).join("")}</div>
              <div class="pk-field-label">Color de pelo</div>
              <div class="pk-row pk-swatches" id="pkHairRow">${PK_HAIRS.map(c=>`<button class="pk-swatch" type="button" data-kind="hair" data-color="${c}" style="background:${c}" aria-label="Pelo ${c}"></button>`).join("")}</div>
            </div>
          </div>
          <div class="pk-creator-actions"><button id="pkCreatorOk" class="btn primary" type="button">¡Comenzar aventura!</button></div>
        </div>`;
        document.body.appendChild(ov);
        $("pkCreatorOk").addEventListener("click",pkConfirmCreator);
        $("pkCreatorCancel").addEventListener("click",()=>{pkCloseCreator();$("mainMenu").classList.remove("hidden");});
        $("pkNameInput").addEventListener("input",e=>{pkDraft.name=e.target.value.trim().slice(0,12);pkRefreshCreator();});
        $("pkGenderM").addEventListener("click",()=>{pkDraft.gender="m";pkRefreshCreator();});
        $("pkGenderF").addEventListener("click",()=>{pkDraft.gender="f";pkRefreshCreator();});
        $("pkHatOn").addEventListener("click",()=>{pkDraft.hat=true;pkRefreshCreator();});
        $("pkHatOff").addEventListener("click",()=>{pkDraft.hat=false;pkRefreshCreator();});
        ov.querySelectorAll(".pk-swatch").forEach(b=>b.addEventListener("click",()=>{pkDraft[b.dataset.kind==="hair"?"hair":"shirt"]=b.dataset.color;pkRefreshCreator();}));
      }
      // Sincroniza marcador y entrenador de espaldas
      setInterval(()=>{
        const fill=$("objectiveFill"),mk=$("pkTrainerMarker");
        if(fill&&mk)mk.style.left=fill.style.width||"0%";
        const tb=$("pkTrainerBack");
        if(tb)tb.classList.toggle("show",!!run);
      },250);
      pkRenderTrainers();
    }catch(e){/* nunca romper el juego */}
  })();

