  const PK_ES2ID={};Object.keys(PK_TYPE_ES).forEach(k=>{PK_ES2ID[PK_TYPE_ES[k].toLowerCase()]=k;});
  function pkBuildHud(slot,ally){
    // La capa HUD pertenece al motor Kanto. Johto clona los mismos IDs dentro de
    // #pkRegionRuntimeRoot y usa su propio render regional; ignorarlo aquí evita
    // que los observers de Kanto intenten resolver IDs Johto contra FAMILIES Kanto.
    if(slot?.closest?.("#pkRegionRuntimeRoot"))return;
    const box=slot.querySelector(".mon")||slot.querySelector(".enemy");if(!box)return;
    let hud=box.querySelector(":scope > .pk-hud");
    if(!hud){hud=document.createElement("div");hud.className="pk-hud";box.appendChild(hud);}
    let row=hud.querySelector(":scope > .pk-hprow");
    if(!row){row=document.createElement("div");row.className="pk-hprow";hud.appendChild(row);}
    const name=slot.querySelector(".mon-name")||slot.querySelector(".enemy-name");
    if(name&&name.parentNode!==hud)hud.insertBefore(name,row);
    const held=box.querySelector(":scope > .held-badge")||slot.querySelector(".held-badge");
    if(held&&held.parentNode!==hud)hud.insertBefore(held,name||row);
    const hp=box.querySelector(":scope > .battle-hp")||slot.querySelector(".battle-hp");
    if(hp&&hp.parentNode!==row)row.appendChild(hp);
    const badge=box.querySelector(".posbadge")||box.querySelector(".levelbadge");
    if(badge&&badge.parentNode!==row)row.appendChild(badge);
    let types=slot.querySelector(".types");
    if(ally){
      const id=(box.id||"").replace("avatar-","");
      const st=(typeof combatStage==="function")?combatStage(id):null;
      const arr=(st&&st.types)||[];
      const sig=arr.join("/");
      if(!types){types=document.createElement("div");types.className="types";slot.appendChild(types);}
      if((types.getAttribute("data-pksig")||"")!==sig){
        types.setAttribute("data-pksig",sig);
        types.innerHTML=arr.map(t=>`<span class="pk-type" style="background:${PK_TYPE_COLOR[t]||"#5b6470"}">${PK_TYPE_ES[t]||t}</span>`).join("");
      }
    }else if(types){
      let raw=types.getAttribute("data-pkraw");
      if(!types.querySelector(".pk-type")){const cur=types.textContent.trim();if(cur&&cur!==raw){raw=cur;types.setAttribute("data-pkraw",raw);}}
      if((types.getAttribute("data-pksig")||"")!==(raw||"")+"#"){
        types.setAttribute("data-pksig",(raw||"")+"#");
        types.innerHTML=(raw||"").split("/").filter(Boolean).map(n=>{
          const id=PK_ES2ID[n.trim().toLowerCase()]||"";
          return `<span class="pk-type" style="background:${PK_TYPE_COLOR[id]||"#5b6470"}">${n.trim()}</span>`;
        }).join("");
      }
    }
    if(types&&types.parentNode!==hud)hud.appendChild(types);
    const img=box.querySelector(":scope > img");
    const allyId=ally?(box.id||"").replace("avatar-",""):"";
    const transformedShiny=!!(ally&&allyId==="ditto"&&run?.team?.[allyId]?.transformData?.active&&run.team[allyId].transformData.shiny);
    const ownedShiny=!!(ally&&allyId&&typeof isOwnedShinyEquipped==="function"&&isOwnedShinyEquipped(allyId));
    const spriteShiny=!!img&&(((img.getAttribute("data-pk-png")||"").indexOf("/shiny/")>=0)||((img.getAttribute("src")||"").indexOf("/shiny/")>=0));
    const shiny=ownedShiny||transformedShiny||spriteShiny;
    let star=box.querySelector(":scope > .pk-shiny-star");
    if(shiny&&!star){star=document.createElement("i");star.className="pk-shiny-star";star.textContent="★";box.appendChild(star);}
    if(!shiny&&star)star.remove();
  }
