  function gymWireUI(){
    $("menuGymsBtn")?.addEventListener("click",()=>openGyms("menu"));
    $("gymHudBtn")?.addEventListener("click",()=>openGyms("game"));
    $("menuProfileBtn")?.addEventListener("click",()=>{if(!state.trainerAvatar){pkOpenCreator(true);return;}openPlayerProfile("menu");});
    $("gymSelectCloseBtn")?.addEventListener("click",closeGyms);
    $("gymBattlePotionBtn")?.addEventListener("click",gymOpenPotion);
    $("gymBattlePauseBtn")?.addEventListener("click",gymTogglePause);
    $("gymBattleForfeitBtn")?.addEventListener("click",gymForfeit);
    $("gymLogTabBtn")?.addEventListener("click",()=>gymSetBattleTab("log"));
    $("gymDamageTabBtn")?.addEventListener("click",()=>gymSetBattleTab("damage"));
    $("gymPotionCloseBtn")?.addEventListener("click",()=>gymClosePotion(true));
    $("gymMonDetailCloseBtn")?.addEventListener("click",()=>gymCloseMonDetail(true));
    $("gymPotionOverlay")?.addEventListener("click",e=>{if(e.target===e.currentTarget)gymClosePotion(true);});
    $("gymMonDetailOverlay")?.addEventListener("click",e=>{if(e.target===e.currentTarget)gymCloseMonDetail(true);});
    for(const id of ["gymPlayerSide","gymEnemySide","gymPlayerReserve","gymEnemyReserve"]){$(id)?.addEventListener("click",e=>{const el=e.target.closest("[data-gym-mon-index]");if(!el)return;gymOpenMonDetail(el.dataset.side,Number(el.dataset.gymMonIndex));});}
    $("gymPlayerTrainer")?.addEventListener("click",e=>{e.stopPropagation();if(gymBattle)openPlayerProfile("gymBattle");});
    for(const id of ["pkTrainerMarker","pkTrainerBack"]){$(id)?.addEventListener("click",e=>{e.stopPropagation();openPlayerProfile("game");});}
    const closeGymResultToSelect=()=>{$("gymResultOverlay")?.classList.add("hidden");renderGymSelect();$("gymSelectOverlay")?.classList.remove("hidden");};
    const closeGymResultToLobby=()=>{$("gymResultOverlay")?.classList.add("hidden");$("gymSelectOverlay")?.classList.add("hidden");try{renderEverything();}catch(_){};};
    $("gymResultContinueBtn")?.addEventListener("click",closeGymResultToSelect);
    $("gymResultCloseTopBtn")?.addEventListener("click",closeGymResultToLobby);
    $("gymResultOverlay")?.addEventListener("click",e=>{if(e.target===e.currentTarget)closeGymResultToLobby();});
    $("gymResultProfileBtn")?.addEventListener("click",()=>{$("gymResultOverlay")?.classList.add("hidden");openPlayerProfile("gyms");});
    $("playerProfileCloseBtn")?.addEventListener("click",closePlayerProfile);
    $("gymSelectOverlay")?.addEventListener("click",e=>{if(e.target===e.currentTarget)closeGyms();});
    $("playerProfileOverlay")?.addEventListener("click",e=>{if(e.target===e.currentTarget)closePlayerProfile();});
  }

