  function gymDifficultyTune(id){
    const base=GYM_DIFFICULTY_TUNE;
    if(!window.PokeSendaRegionBoot?.isHoennClone)return base;
    const p=HOENN_GYM_PRESSURE[id]||HOENN_GYM_PRESSURE.brock;
    return {hp:base.hp*p.hp,offense:base.offense*p.offense,defense:base.defense*p.defense,speed:base.speed*p.speed};
  }
