  const GYM_STATE_TEMPLATE={badges:[],wins:{},attempts:{},bestTimes:{},firstWinAt:{},lastTeam:{},leagueUnlocked:false};
  function normalizeGymState(){
    const raw=(state.gyms&&typeof state.gyms==="object")?state.gyms:{};
    state.gyms={...GYM_STATE_TEMPLATE,...raw};
    state.gyms.badges=[...new Set((Array.isArray(state.gyms.badges)?state.gyms.badges:[]).filter(x=>GYM_ORDER.includes(x)))];
    for(const k of ["wins","attempts","bestTimes","firstWinAt","lastTeam"]){if(!state.gyms[k]||typeof state.gyms[k]!=="object"||Array.isArray(state.gyms[k]))state.gyms[k]={};}
    state.gyms.leagueUnlocked=state.gyms.badges.length>=8;
    return state.gyms;
  }
  normalizeGymState();
  function gymBadgeCount(){return normalizeGymState().badges.length;}
  function gymHasBadge(id){return normalizeGymState().badges.includes(id);}
  function gymUnlocked(id){const i=GYM_ORDER.indexOf(id);return i===0||(i>0&&gymHasBadge(GYM_ORDER[i-1]));}
  function gymNextId(){return GYM_ORDER.find(id=>!gymHasBadge(id))||null;}
  function gymStageMeta(dex){return stageMetaByDex(Number(dex));}
